INSERT IGNORE INTO `unlisted_stocks` (`UL_STOCKS_FINCODE`, `UL_STOCKS_COMPNAME`, `UL_STOCKS_SLUG`, `UL_STOCKS_LOGO_LINK`, `UL_STOCKS_IND_CODE`, `UL_STOCKS_INDUSTRY`, `UL_STOCKS_ISIN`, `UL_STOCKS_S_NAME`, `UL_STOCKS_CHAIRMAN`, `UL_STOCKS_MDIR`, `UL_STOCKS_CATEGORY`, `UL_STOCKS_INC_MONTH`, `UL_STOCKS_INC_YEAR`, `UL_STOCKS_STATUS`, `UL_STOCKS_ADD1`, `UL_STOCKS_ADD2`, `UL_STOCKS_ADD3`, `UL_STOCKS_CITY_NAME`, `UL_STOCKS_PINCODE`, `UL_STOCKS_STATE_NAME`, `UL_STOCKS_PHONE`, `UL_STOCKS_FAX_NO`, `UL_STOCKS_WEBSITE`, `UL_STOCKS_E_MAIL`, `UL_STOCKS_ABOUT`, `UL_STOCKS_INSERT_BY`, `UL_STOCKS_INSERT_TIME`, `UL_STOCKS_UPDATE_TIME`, `UL_STOCKS_COMP_RATING`, `UL_STOCKS_VALUATION_RATING`, `UL_STOCKS_LOT_SIZE`, `UL_STOCKS_ROFR_FLAG`, `UL_STOCKS_DEMAT_ACCOUNT_REQ`, `UL_STOCKS_BUY_SELL_FLAG`, `UL_STOCKS_COMPNAME_TYPE`, `UL_STOCKS_Qtr_Data_Publish`) VALUES
(100021, 'Nayara Energy Ltd', 'nayara-energy-ltd', 'images/company-logo/nayara-energy-ltd.png', NULL, 'Refineries', 'INE011A01019', 'Nayara Energy', NULL, NULL, 'pre_ipo', NULL, '1989', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.nayaraenergy.com/', NULL, 'Nayara Energy, headquartered in Mumbai, is a downstream oil-and-petrochemicals company with an international footprint. The business traces back to 1989 and operated as Essar Oil Limited until it was rebranded Nayara Energy in May 2018.\n\nThe company refines crude oil and markets petroleum products across India, South Africa, Singapore, Mozambique, the UAE and other markets, with a product slate that includes bitumen, fly ash, high-speed diesel, high-flash high-speed diesel, petcoke and sulphur. Its refinery — one of India\'s largest single-site facilities — runs at 20 MTPA capacity with a complexity index of 11.8, accounting for roughly 8% of the country\'s total refining capacity, and the company is present across the hydrocarbon chain from refining through to marketing, with plans in motion to move further into crude-to-chemicals. It also runs one of India\'s fastest-growing fuel retail networks.\n\nOwnership changed hands in a leveraged buyout that closed on 30 December 2015, when the company was taken private. It was subsequently acquired in 2016 by Rosneft — the world\'s largest publicly traded oil and gas producer by liquid-hydrocarbon output and reserves — alongside an investment consortium led by Trafigura and UCP Investment Group.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '5', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100022, 'Inox Clean Energy Limited', 'inox-clean-energy-limited', 'images/company-logo/inox-clean-energy-limited.png', NULL, 'Power Generation/Distribution', 'INE0H7K01023', 'Inox Clean Energy', NULL, NULL, 'pre_ipo', NULL, '2017', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://inoxclean.com/', NULL, 'Inox Clean Energy Limited, part of the INOXGFL Group, is building out an integrated green-energy business in India. Its core focus is manufacturing solar cells and modules and putting them to work in captive and third-party hybrid power projects.\n\nWhat sets its model apart is the pairing of solar manufacturing with independent-power-producer operations, run through its arm Inox Neo Energies Ltd, which lets it supply captive users, commercial and industrial customers, and power exchanges alike. The company has also grown inorganically — a 50 MW solar asset in Madhya Pradesh among its acquisitions — while working toward multi-gigawatt hybrid wind-and-solar projects.\n\nWith innovation, sustainability and energy efficiency as recurring themes in how it describes itself, Inox Clean Energy is positioning itself as one of the companies pushing India toward a cleaner energy mix.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '4', NULL, '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100023, 'Capgemini Technology Services India Limited', 'capgemini-technology-services-india-limited', 'images/company-logo/capgemini-technology-services-india-limited.png', 155, 'e-Commerce', 'INE177B01032', 'Capgemini Technology', NULL, NULL, 'pre_ipo', 'December', '1993', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.capgemini.com/in-en/', NULL, 'Capgemini Technology Services India Limited (CTSIL), incorporated on 27 December 1993, is the Indian arm of the global technology and consulting major Capgemini, working with businesses on managing and transforming operations through technology. Services span IT-enabled operations, BPO, application re-engineering, and custom or packaged application development, among others.\n\nPreviously known as IGATE Global Solutions Limited at the time of incorporation, the company runs development centres across Bengaluru, Chennai, Pune, Mumbai and Hyderabad. Globally, the Capgemini group counts around 325,000 employees and a presence in more than 50 countries.\n\nClients lean on Capgemini to cover the full spread of business needs — from strategy through to day-to-day operations — powered by technology areas such as cloud, data, connectivity, AI and digital engineering.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '5', '4', '2', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100024, 'Anheuser Busch Inbev (Sabmiller) India Ltd', 'anheuser-busch-inbev-sabmiller-india-ltd', 'images/company-logo/anheuser-busch-inbev-sabmiller-india-ltd.png', NULL, 'Breweries & Distilleries', 'INE038G01019', 'AB Inbev Sabmiller', NULL, NULL, 'pre_ipo', NULL, '1988', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.abinbev-india.com/', NULL, 'Anheuser-Busch InBev (AB InBev), formed in 2016 through the merger of Anheuser-Busch and InBev, is one of the world\'s largest brewing companies and has an established presence in India through its subsidiary SabMiller India. The India business is known for beer brands such as Haywards 5000, Royal Challenge, Knock Out and Foster\'s, supported by a wide distribution network and breweries spread across the country.\n\nAB InBev has continued to put money into its Indian operations — modernising breweries, tightening up the supply chain, and widening distribution — which has helped it hold its ground and grow share in a competitive market. The company also takes part in various community-linked initiatives as part of its presence in the country.\n\nQuality control is a consistent theme in how the company positions itself, with products built to international standards and ongoing investment in equipment and technology — factors that have helped the brand build trust among Indian consumers over time.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100025, 'Zepto Limited', 'zepto-limited', 'images/company-logo/zepto-limited.png', 155, 'e-Commerce', 'INE143401029', 'Zepto', NULL, NULL, 'pre_ipo', NULL, '2020', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.zeptonow.com/', NULL, 'Zepto Limited runs one of India\'s fastest-growing quick-commerce platforms, built around delivering groceries and daily essentials to customers in major cities in roughly 10 minutes. It was founded by Aadit Palicha (CEO) and Kaivalya Vohra (CTO), two young founders who left Stanford to build the company, and its approach to last-mile logistics rests on a dense network of dark stores — small urban fulfilment hubs — combined with technology-led routing to get orders out fast.\n\nHeadquartered in Bengaluru, Zepto lists tens of thousands of products across fresh produce, packaged goods, household items and more, and has since branched into adjacent services such as Zepto Cafe and pharmacy/diagnostics. The company has drawn substantial funding from major global investors and now carries a multi-billion-dollar valuation, putting it among the leading names in India\'s crowded quick-commerce race alongside rivals like Blinkit and Swiggy Instamart.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '5', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100026, 'Goa Shipyard Limited', 'goa-shipyard-limited', 'images/company-logo/goa-shipyard-limited.png', NULL, 'Defence', 'INE178Z01013', 'Goa Shipyard', NULL, NULL, 'pre_ipo', NULL, '1957', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://goashipyard.in/', NULL, 'Goa Shipyard Limited is a Government of India-owned defence shipbuilder based in Vasco da Gama, Goa, functioning under the Ministry of Defence. It began life in 1957 as Estaleiros Navais de Goa, initially building barges for the mining industry, and moved into defence shipbuilding after Goa\'s integration with India in 1961.\n\nThe company now designs and builds a range of naval and coast-guard vessels — offshore patrol vessels, fast patrol vessels, frigates, interceptor boats, pollution-control vessels, survey ships and other specialised craft — for the Indian Navy, Indian Coast Guard, and international customers as well.\n\nOver the decades, Goa Shipyard has built up considerable shipbuilding infrastructure and technical capability, delivering hundreds of vessels and playing a fairly central role in India\'s push toward indigenous maritime-defence manufacturing and coastal security.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100027, 'SBI General Insurance Company Limited', 'sbi-general-insurance-company-limited', 'images/company-logo/sbi-general-insurance-company-limited.png', NULL, 'Insurance', 'INE01MM01017', 'SBI General Insurance', NULL, NULL, 'pre_ipo', NULL, '2009', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.sbigeneral.in/', NULL, 'SBI General Insurance Company Limited, incorporated in 2009 as a subsidiary of State Bank of India, ranks among India\'s leading private general insurers. Its product range covers health, motor, travel, home, personal accident and commercial insurance for both individuals and businesses.\n\nBacked by SBI\'s extensive banking network and brand strength, the company has built a wide presence through branches, network hospitals and garages across the country. A focus on digital-first, customer-centric insurance and faster claim settlement has helped it establish itself as one of the more prominent names in India\'s general insurance space.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '3', '4', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100028, 'Big Basket', 'big-basket', 'images/company-logo/big-basket.png', 155, 'e-Commerce', 'INE058T01010', 'Big Basket', NULL, NULL, 'pre_ipo', NULL, '2011', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.bigbasket.com/', NULL, 'BigBasket, launched in 2011 and headquartered in Bengaluru, runs India\'s largest online grocery delivery service under the entity Innovative Retail Concepts Private Limited. The platform stocks a wide catalogue — fresh produce, dairy, staples, beverages, personal care and household essentials — and reaches millions of customers across Indian cities through scheduled delivery, express delivery and subscription-based models.\n\nTata Digital, a Tata Group subsidiary, acquired BigBasket in 2021, adding to its market presence and technology capability. The company today runs several distinct verticals, including BB Daily for milk and daily essentials, BB Instant\'s smart vending machines, and BB Now for quick commerce — with quality, convenience and product breadth remaining central to its pitch as a go-to platform for online grocery shopping in India.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '4', '4', '2500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100029, 'Inox Leasing and Finance Limited', 'inox-leasing-and-finance-limited', 'images/company-logo/inox-leasing-and-finance-limited.png', 50, 'Finance - NBFC', 'INE608E01014', 'Inox Leasing and Finance', NULL, NULL, 'pre_ipo', 'February', '1995', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://ilfl.co.in/', NULL, 'Inox Leasing and Finance Limited (ILFL), incorporated in February 1995 and registered in Himachal Pradesh, is a non-deposit-taking NBFC registered with the RBI. Its business runs across financing and leasing, investments in shares, bonds and mutual funds, brokerage income from mutual funds, and wind-energy generation.\n\nILFL also functions as a holding company for major group entities, including Gujarat Fluorochemicals Limited (GFCL) and Inox Wind Energy Limited (IWEL). More recently, it has gone through a structural reorganisation — a scheme to demerge the wind business and merge the remaining entity into GFCL — aimed at simplifying the group structure and unlocking value.\n\nTaken together, ILFL functions as a diversified NBFC with sizeable investment holdings across industrial and energy-linked sectors, built around long-term growth and value creation.', '6', '2026-08-24 15:57:01', '2026-08-24 15:57:01', '4', '4', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100030, 'Jupiter International Limited', 'jupiter-international-limited', 'images/company-logo/jupiter-international-limited.png', 142, 'Other', 'INE467C01027', 'Jupiter International', NULL, NULL, 'pre_ipo', NULL, '1978', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://jil-jupiter.com/', NULL, 'Jupiter International Limited started out in jute trading back in 1978 and has since evolved into a name in solar-energy manufacturing. Along the way it diversified into computer peripherals and optical media under the \"Frontech\" brand before eventually pivoting toward renewable energy.\r\n\r\nSince 2009, the company has built out its solar photovoltaic business and now runs a modern manufacturing facility in Baddi, Himachal Pradesh, with a meaningful solar-cell production capacity. Recent years have seen faster growth on the back of large investments aimed at building a fully integrated solar value chain — wafers, cells and modules — alongside expansion plans covering new facilities and partnerships meant to strengthen its position within India\'s clean-energy space.', '6', '2026-08-24 15:57:01', '2026-08-25 07:42:45', '4', '4', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100031, 'PPFAS - Parag Parikh Financial Advisory Services', 'ppfas-parag-parikh-financial-advisory-services', 'images/company-logo/ppfas-parag-parikh-financial-advisory-services.png', 157, 'Finance - Others', 'INE0FGC01012', 'Parag Parikh Financial Advisory Services', NULL, NULL, 'pre_ipo', NULL, '1992', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.ppfas.com/', NULL, 'Parag Parikh Financial Advisory Services Ltd. (PPFAS) got its start in 1992 in Mumbai, offering advisory and transaction services on the BSE before expanding to the NSE. By 1996, it had become one of the first Indian firms licensed to offer Portfolio Management Services. Its flagship PMS scheme, Cognito, has been closed to new clients for well over a decade — a reflection of the firm\'s fairly selective, long-term approach to managing money.\n\nPPFAS also sponsors PPFAS Mutual Fund, which launched its first scheme in May 2013. The fund house now runs around five to six schemes, including the well-known Parag Parikh Flexi Cap Fund, an ELSS Tax Saver Fund, a Liquid Fund, a Conservative Hybrid Fund and an Arbitrage Fund.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '50', 'No', 'Both', 'Yes', 'unlisted', 'Yes'),
(100032, 'IndusInd General Insurance Company Limited', 'indusind-general-insurance-company-limited', 'images/company-logo/indusind-general-insurance-company-limited.png', NULL, 'Insurance', 'INE124D01014', 'IndusInd General Insurance', NULL, NULL, 'pre_ipo', NULL, '2000', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.indusindinsurance.com/', NULL, 'IndusInd General Insurance Company Limited, established in 2000 and formerly known as Reliance General Insurance, now operates under IndusInd International Holdings Limited (IIHL) and ranks among India\'s leading private general insurers. Headquartered in Mumbai, it covers motor, health, travel, home, marine and commercial insurance for individuals, SMEs and corporates.\n\nThe company reaches customers through a wide distribution mix — branch offices, intermediaries, bancassurance tie-ups and digital channels — with an emphasis on customer-centric service, technology and efficient claims handling. It has also rolled out newer products designed around shifting consumer needs and regulatory changes, aiming to make insurance more accessible and affordable as it grows within India\'s non-life insurance market.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100033, 'Care Health Insurance Ltd', 'care-health-insurance-ltd', 'images/company-logo/care-health-insurance-ltd.png', NULL, 'Insurance', 'INE119J01011', 'Care Health Insurance', NULL, NULL, 'pre_ipo', NULL, '2007', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.careinsurance.com/', NULL, 'Care Health Insurance Company, incorporated on 2 April 2007 and formerly known as Religare Health, operates as a direct subsidiary of Religare Enterprises Limited. As a specialised health insurer, it covers individuals, families and corporates through products spanning health insurance, top-up coverage, personal accident, maternity, international travel insurance, critical illness, and group health and personal-accident insurance.\n\nThe company\'s network runs to 110 branches and more than 9,450 network hospitals across the country, with an 18-product portfolio built to serve a fairly wide range of customers, from group and travel cover to fixed-benefit plans.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '2', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100034, 'Hero Fincorp Limited', 'hero-fincorp-limited', 'images/company-logo/hero-fincorp-limited.png', 50, 'Finance - NBFC', 'INE957N01016', 'Hero Fincorp', NULL, NULL, 'pre_ipo', 'December', '1991', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.herofincorp.com/', NULL, 'Hero FinCorp, incorporated in December 1991 under the name Hero Honda FinLease Ltd., is an Indian NBFC active in leasing, financing, bill discounting and related businesses, spanning both consumer finance and commercial lending.\n\nIts product range includes retail loans, corporate loans and loyalty-linked loans — two-wheeler, personal, used-car and commercial loans, loans against property, unsecured business loans, medical-equipment financing, working-capital loans and inventory funding, among others. The company runs through roughly 2,000 retail touch-points across India and works with more than 2,000 corporate clients.\n\nA subsidiary, Hero Housing Finance Limited, focuses on end-to-end digital lending built around making home ownership a smoother experience for customers.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100035, 'Hero Motors Limited', 'hero-motors-limited', 'images/company-logo/hero-motors-limited.png', NULL, 'Automobile Two & Three Wheelers', 'INE012G01022', 'Hero Motors', NULL, NULL, 'pre_ipo', NULL, '1998', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.heromotors.com/', NULL, 'Hero Motors Limited, founded in 1998 and headquartered in Gautam Budh Nagar, Uttar Pradesh, is an automotive component manufacturer and engineering-solutions provider under the HMC (Hero Motors Company) Group. The business specialises in powertrain solutions, gears and transmission systems, and alloy and metallic parts supplied to leading global OEMs across motorcycles, automotive, off-road and EV segments.\n\nWith over a thousand employees and manufacturing units spread across India and abroad, the company draws on in-house R&D and international tie-ups — including one with UK-based Hewland Engineering — to deliver system-level products for both ICE and electric powertrains, e-bikes and performance vehicles, serving customers across the US, Europe, India and ASEAN. Innovation, quality and cost-effective engineering remain recurring themes as it continues to widen its global reach.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '500', 'No', 'Both', 'Yes', 'unlisted', 'No');
INSERT IGNORE INTO `unlisted_stocks` (`UL_STOCKS_FINCODE`, `UL_STOCKS_COMPNAME`, `UL_STOCKS_SLUG`, `UL_STOCKS_LOGO_LINK`, `UL_STOCKS_IND_CODE`, `UL_STOCKS_INDUSTRY`, `UL_STOCKS_ISIN`, `UL_STOCKS_S_NAME`, `UL_STOCKS_CHAIRMAN`, `UL_STOCKS_MDIR`, `UL_STOCKS_CATEGORY`, `UL_STOCKS_INC_MONTH`, `UL_STOCKS_INC_YEAR`, `UL_STOCKS_STATUS`, `UL_STOCKS_ADD1`, `UL_STOCKS_ADD2`, `UL_STOCKS_ADD3`, `UL_STOCKS_CITY_NAME`, `UL_STOCKS_PINCODE`, `UL_STOCKS_STATE_NAME`, `UL_STOCKS_PHONE`, `UL_STOCKS_FAX_NO`, `UL_STOCKS_WEBSITE`, `UL_STOCKS_E_MAIL`, `UL_STOCKS_ABOUT`, `UL_STOCKS_INSERT_BY`, `UL_STOCKS_INSERT_TIME`, `UL_STOCKS_UPDATE_TIME`, `UL_STOCKS_COMP_RATING`, `UL_STOCKS_VALUATION_RATING`, `UL_STOCKS_LOT_SIZE`, `UL_STOCKS_ROFR_FLAG`, `UL_STOCKS_DEMAT_ACCOUNT_REQ`, `UL_STOCKS_BUY_SELL_FLAG`, `UL_STOCKS_COMPNAME_TYPE`, `UL_STOCKS_Qtr_Data_Publish`) VALUES
(100036, 'boAt - Imagine Marketing Limited', 'boat-imagine-marketing-limited', 'images/company-logo/boat-imagine-marketing-limited.png', NULL, 'Electronics - Components', 'INE03AV01027', 'BOAT', NULL, NULL, 'pre_ipo', NULL, '2013', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.boat-lifestyle.com/', NULL, 'Imagine Marketing Limited, better known by its consumer brand boAt, is headquartered in Mumbai and was founded on 1 November 2013. The company manufactures and sells consumer-electronics products in India and overseas, built around a portfolio of lifestyle-focused goods priced to be broadly accessible.\n\nIts audio lineup under the Boat name covers wired and wireless headphones, neckbands, true wireless stereo earbuds, Bluetooth speakers, home-theatre systems and soundbars. Beyond audio, the company sells smartwatches, gaming peripherals such as headsets, mice and keyboards, personal-care products like trimmers and grooming kits, and mobile accessories including chargers, cables and power banks — sold across brand names such as boAt, RedGear, TAGG, Misfit and DEFY.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100037, 'Incred Holdings Limited', 'incred-holdings-limited', 'images/company-logo/incred-holdings-limited.png', 50, 'Finance - NBFC', 'INE732W01014', 'Incred Holdings', NULL, NULL, 'pre_ipo', NULL, '2016', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.incred.com/', NULL, 'InCred Holdings Limited, headquartered in Mumbai, is a diversified financial-services company founded in 2016 by Bhupinder Singh, a former Deutsche Bank executive. The InCred Group spans consumer lending, education financing, MSME loans, asset and wealth management, investment banking and digital investment distribution, and now runs with over 3,500 employees across more than 150 locations in India.\n\nIts model blends conventional lending with a heavy reliance on technology and data analytics, which the company credits for helping it scale while keeping risk in check. Milestones along the way include launching NBFC operations in 2016, acquiring fintech platform Qbera in 2020, and building partnerships with platforms such as Amazon and Flipkart. InCred reached unicorn status after merging with KKR India Financial Services and closing a ₹500 crore Series D round.\n\nOn the numbers, the group\'s AUM grew to roughly ₹9,000 crore in FY24, with profit after tax of ₹309 crore and collection efficiency holding near 98%. Gross and net NPAs sit around 2.1%, while capital adequacy remains strong at close to 33%. The company points to its diversified lending mix, tech-driven risk assessment, capital backing from investors like KKR, and governance structure as its key strengths.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100038, 'Shriram Life Insurance Company Limited', 'shriram-life-insurance-company-limited', 'images/company-logo/shriram-life-insurance-company-limited.png', NULL, 'Insurance', 'INE227H01016', 'Shriram Life Insurance', NULL, NULL, 'pre_ipo', NULL, '2005', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.shriramlife.com/', NULL, 'Shriram Life Insurance Company is built around bringing life-insurance coverage to a wider cross-section of Indian households, with particular attention to families most exposed to the financial fallout of losing a breadwinner. Operational discipline, integrity and a clear focus on serving the average Indian customer with reasonably priced products sit at the core of how the company describes its own values.\n\nThe insurer places a fair amount of emphasis on understanding its customers, with products and services shaped around what different customer segments actually need. That customer-first approach has, over time, helped widen the group\'s reach — and it has become a go-to name for truck-finance-linked insurance needs among its client base.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100039, 'Inox Renewable Solutions Limited', 'inox-renewable-solutions-limited', 'images/company-logo/inox-renewable-solutions-limited.png', NULL, 'Power Generation/Distribution', 'INE0CJZ01014', 'Inox Renewable Solutions', NULL, NULL, 'pre_ipo', NULL, '2020', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://inoxrenewables.com/', NULL, 'Inox Renewable Solutions Limited, earlier known as Resco Global Wind Services Pvt. Ltd., is an EPC company focused on renewable energy, operating as a subsidiary of Inox Wind Limited within the INOXGFL Group. Its services cover the full project cycle for wind-energy projects — resource assessment, site acquisition, infrastructure development, turbine erection, commissioning and power evacuation — delivered largely on a turnkey basis across India.\n\nWith more than 14 years in the business, the company has built itself into a fairly established name in executing large-scale renewable projects, and it\'s also working on multi-gigawatt shared evacuation infrastructure meant to support India\'s growing renewable capacity and broader clean-energy goals.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', NULL, '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100040, 'Taparia Tools Limited', 'taparia-tools-limited', 'images/company-logo/taparia-tools-limited.png', NULL, 'Trading', 'INE614R01014', 'Taparia Tools', NULL, NULL, 'pre_ipo', NULL, '1965', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.tapariatools.com/', NULL, 'Taparia Tools, founded in 1965 and headquartered in Mumbai, is primarily a manufacturer and trader of hand tools in India. Its catalogue spans adjustable spanners, mini pliers, screwdriver bits and sets, tool sets, sockets and socket accessories, torque wrenches, hammers, clamps, wheel spanners, chisels, punches, magnetic products, cutters, hacksaw blades, gear pullers, Allen keys and sets, tool trolleys, spirit levels and non-sparking tools.\n\nThe company runs two manufacturing facilities — one in Goa and one in Nashik — with the Nashik plant spread across roughly 42,832 square metres and all manufacturing units housed under a single roof. Production draws on technology adapted from a Swedish collaboration, and the plant also runs a dedicated Quality Control department and lab for testing raw materials right through to finished goods.\n\nTaparia sells under its own brand name through a network of more than 800 distributors and exports to markets including the UK, US, Denmark, Germany, Sweden, Dubai, Norway, Finland, Israel, Kuwait, Kenya, Hong Kong, Thailand, Mexico, Argentina and Sri Lanka.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100041, 'Manjushree Technopack India Limited', 'manjushree-technopack-india-limited', 'images/company-logo/manjushree-technopack-india-limited.png', NULL, 'Packaging', 'INE435H01023', 'Manjushree Technopack', NULL, NULL, 'pre_ipo', NULL, '1987', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.manjushreetechnopack.com/', NULL, 'Manjushree Technopack India Limited holds the position of India\'s largest rigid plastic packaging (RPP) player by installed capacity. It works as a one-stop packaging partner across the consumer rigid plastics space, covering the full value chain from design through to delivery.\n\nIts product range includes containers, preforms, caps and closures, pumps and dispensers, alongside in-house recycling capability. Manjushree\'s client base runs across food and beverages, home care, personal care, liquor and spirits, paints and adhesives, pharmaceuticals, nutraceuticals, dairy, automotive and agrochemicals — a fairly broad industry spread for a packaging specialist.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100042, 'Manipal Payment and Identify Solutions Ltd', 'manipal-payment-and-identify-solutions-ltd', 'images/company-logo/manipal-payment-and-identify-solutions-ltd.png', 142, 'Other', 'INE241U01028', 'Manipal Cards', NULL, NULL, 'pre_ipo', 'February', '2008', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://mpimanipal.com/', NULL, 'Manipal Payment and Identity Solutions Ltd (MPi), incorporated in February 2008 and headquartered in Manipal, Karnataka, operates as a subsidiary of Manipal Technologies Limited (MTL) within the wider Manipal Group. The company focuses on secure payment and identity solutions, handling manufacturing, personalisation and fulfilment end to end.\n\nIts product line covers EMV-compliant payment cards in both plastic and metal, smart cards, government-issued ID cards, tax stamps, smart wearables, RFID tags and other secure-printing products. MPi\'s client base spans banks and financial institutions, fintechs and government agencies, both within India and overseas, and the company leans on its manufacturing scale and global certifications to position itself among the leading names in India\'s payment-and-identity-solutions space.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100043, 'Indian Potash Ltd', 'indian-potash-ltd', 'images/company-logo/indian-potash-ltd.png', NULL, 'Agriculture', 'INE863S01015', 'Indian Potash', NULL, NULL, 'pre_ipo', NULL, '1955', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.indianpotash.org/', NULL, 'Indian Potash Limited (IPL), established on 17 June 1955 and headquartered in Chennai, functions as a wholly owned subsidiary of the Indian Farmers Fertiliser Cooperative. The company is a major importer of muriate of potash, di-ammonium phosphate, sulphate of potash, urea, rock phosphate, gypsum and related inputs. It was originally known as Indian Potash Supply Agency before adopting its current name in 1970.\n\nIPL runs two cattle-feed plants — in Sikandrabad and Renigunta — serving the needs of northern and southern India respectively. Beyond potash-fertiliser imports, handling and marketing, the company\'s activities extend to fertiliser manufacturing, milk and milk products, sulphitation of milk and fertiliser, refined sugar, and trading in gold and other precious metals.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100044, 'Philips India Limited', 'philips-india-limited', 'images/company-logo/philips-india-limited.png', NULL, 'Medical Equipment/Supplies/Accessories', 'INE319A01016', 'Philips India', NULL, NULL, 'pre_ipo', NULL, '1930', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.philips.co.in/', NULL, 'Philips India Limited operates as part of Royal Philips of the Netherlands, a group focused on improving health outcomes across the care continuum — from healthy living and prevention through to diagnosis and home care. In India, the company has built a reputation as a high-tech player in personal health and care systems.\n\nIts India presence includes a healthcare-innovation hub in Pune and an innovation campus in Bangalore, both geared toward developing improvements meant to support people\'s well-being and health more broadly.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100045, 'Elcid Investments Limited', 'elcid-investments-limited', 'images/company-logo/elcid-investments-limited.png', 50, 'Finance - NBFC', 'INE927X01018', 'Elcid Investments', NULL, NULL, 'pre_ipo', 'December', '1981', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://elcidinvestments.com/', NULL, 'Elcid Investments Limited, incorporated on 3 December 1981 under the Companies Act 1956 and based in Mumbai, is a Non-Banking Finance Company registered with the RBI. As of March 2019, it had two subsidiaries — Suptaswar Investment and Trading Co. Ltd. and Murahar Investment and Trading Co. Ltd. — both of which are themselves RBI-registered NBFCs.\n\nThe company\'s core business lies in investing across listed and unlisted shares, debentures, mutual funds and similar instruments.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '1', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100046, 'ASK Investment Managers Limited', 'ask-investment-managers-limited', 'images/company-logo/ask-investment-managers-limited.png', NULL, 'Finance - Asset Management', 'INE925L01025', 'ASK Investment Managers', NULL, NULL, 'pre_ipo', NULL, '1983', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.askfinancials.com/', NULL, 'ASK Investment Managers Limited (ASKIM) is the flagship discretionary listed-equity asset manager within the ASK Asset & Wealth Management Group, founded in 1983 and headquartered in Mumbai. It works exclusively in discretionary management of Indian listed equities, serving HNIs, ultra-HNI families, institutions, pension funds, endowments, sovereign wealth funds and family offices.\n\nThe firm has notched several sector firsts along the way — among the earliest Portfolio Management Companies licensed by SEBI, the first PMS to operate out of GIFT City for overseas investors, and the first to launch Alternative Investment Funds with digital client onboarding — which the company points to as evidence of its focus on innovation.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100047, 'Sterlite Electric Limited', 'sterlite-electric-limited', 'images/company-logo/sterlite-electric-limited.png', NULL, 'Power Generation/Distribution', 'INE110V01015', 'Sterlite Electric', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.sterlitepower.com/', NULL, 'Sterlite Power Transmission Limited, incorporated on 5 May 2015 and headquartered in Delhi, is a global developer and solutions provider in integrated power transmission. As of 31 March 2021, it employed 715 people in India and 68 in Brazil, alongside 912 temporary or contract workers.\n\nThe company has positioned itself as an innovator within India\'s transmission sector, working to bring in globally accepted best practices to what has historically been a fairly legacy-driven industry, and pushing newer, more efficient technologies to serve customer-specific needs. Serentica, an affiliate of Sterlite Power, provides end-to-end energy solutions aimed at helping energy-intensive industries move faster toward clean power.\n\nSterlite Power\'s core offering covers customised, integrated solutions for upgrading, uprating and fiberising existing transmission infrastructure, alongside a product portfolio of high-performance power conductors, extra-high-voltage cables and optical ground wires geared toward a greener, more efficient energy future.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100048, 'Electrosteel Steel Ltd - ESL Steel', 'electrosteel-steel-ltd-esl-steel', 'images/company-logo/electrosteel-steel-ltd-esl-steel.png', NULL, 'Steel & Iron Products', 'INE481K01021', 'Electrosteel Steel', NULL, NULL, 'pre_ipo', NULL, '2006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.eslsteel.com/', NULL, 'ESL Steel Limited, formerly Electrosteel Steels Limited, is an integrated steel producer based in Bokaro, Jharkhand, originally set up as a public limited company in 2006. Vedanta Limited took over management control in June 2018 through the Corporate Insolvency Resolution Process, the mechanism set up to resolve stressed loans in the Indian banking system.\n\nThe company runs an integrated production facility with capacity for around 2.5 million tonnes annually, built around sinter plants, coke ovens, blast furnaces, oxygen plants, basic oxygen furnaces, billet casters, wire rod mills, bar mills, ductile-iron-pipe plants and a captive power plant. Its product range spans pig iron, billets, TMT bars, wire rods and ductile iron pipes.\n\nThe company was renamed from Electrosteel Steels Limited to ESL Steel Limited on 26 September 2020, and it operates within established environmental norms while drawing on technology and expertise from established global manufacturers.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100049, 'Carrier Airconditioning and Refrigeration Limited', 'carrier-airconditioning-and-refrigeration-limited', 'images/company-logo/carrier-airconditioning-and-refrigeration-limited.png', 155, 'e-Commerce', 'INE040I01011', 'Carrier Airconditioning', NULL, NULL, 'pre_ipo', NULL, '1936', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.carrier.com/commercial/en/in/', NULL, 'Carrier Airconditioning and Refrigeration Limited, founded in 1936 and headquartered in Gurugram, operates as the Indian subsidiary of US-based Carrier Global Corporation. The company manufactures, supplies and trades air conditioners and refrigeration equipment in India and internationally.\n\nIts commercial product range covers cassette and ducted AC systems, chillers and heat pumps, air handlers, floor-standing units, VRF systems, fan coils, air purifiers, and fire-and-security products, alongside services such as installation, repair, maintenance, and retrofitting.\n\nCarrier runs India\'s largest AC manufacturing plant in Bawal, Haryana, with capacity to produce more than 700,000 units a year, supported by 14 sales-and-service offices and a network of over 800 channel partners across the country.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100050, 'Fincare Small Finance Bank Limited', 'fincare-small-finance-bank-limited', 'images/company-logo/fincare-small-finance-bank-limited.png', 15, 'Bank - Private', 'INE519Q08079', 'Fincare Small Finance Bank', NULL, NULL, 'pre_ipo', NULL, '2017', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.au.bank.in/au-small-finance-bank-and-fincare-small-finance-bank-merger', NULL, 'Fincare Small Finance Bank began banking operations in May 2017 as a small finance bank, running its retail business across treasury, corporate banking, wholesale banking and retail banking segments. Its offerings include savings and current accounts, fixed and recurring deposits, retail term deposits, NRI services, and WhatsApp, mobile and internet banking, alongside a loan book covering micro loans, housing, two-wheeler loans, loans against property and gold, and institutional finance.\r\n\r\nThe bank\'s customer base leans heavily toward unbanked and under-banked segments, particularly in rural and semi-urban India, and it uses technology to reach these markets. Its physical and digital footprint spans 528 banking outlets, 219 business-correspondent outlets and 108 ATMs across 16 states, covering 192 districts and 38,809 villages.\r\n\r\nFincare was earlier registered as an NBFC-MFI under the name Disha Microfin Limited. It acquired the micro-finance operations of Future Financial Services Pvt. Ltd and later took on the Fincare Small Finance Bank name once it received RBI\'s in-principle approval.', '6', '2026-08-24 16:10:51', '2026-08-25 08:19:52', '4', '2', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100051, 'Signify Innovations India Limited', 'signify-innovations-india-limited', 'images/company-logo/signify-innovations-india-limited.png', NULL, 'Consumer Durables - Domestic Appliances', 'INE045U01015', 'Signify Innovations', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.signify.com/en-in', NULL, 'Signify Innovations India Limited, incorporated in 2015 and part of the Dutch multinational Signify (formerly known as Philips Lighting), manufactures electric lights and light fixtures for both consumer and professional markets. The company holds a leading position across conventional lighting, LED and connected lighting, with its energy-efficient products aimed at delivering comfort and better-quality lighting.\n\nSignify has been fairly central to the development of connected lighting systems and services, a position that has also made it a notable name in Internet-of-Things applications. In 2018, it became the first global lighting company to enable LiFi on office lighting fixtures — a technology that gets around WiFi connectivity issues by delivering stable broadband connectivity through light waves.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '20', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100052, 'Ticker Limited', 'ticker-limited', 'images/company-logo/ticker-limited.png', 157, 'Finance - Others', 'INE0JS401010', 'Ticker', NULL, NULL, 'pre_ipo', 'February', '2005', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.tickermarket.com/', NULL, 'Ticker Limited, incorporated in February 2005 and headquartered in Mumbai, works in real-time financial data, news and analytics, serving a wide range of financial institutions through its proprietary platform. Coverage spans equities, commodities, fixed income, currencies, agricultural products, energy and virtual digital assets, delivered through ultra-low-latency feeds combined with analytical tools and secure delivery infrastructure.\n\nIts services include end-of-day data, real-time news, wealth analytics, and dedicated solutions for F&O and agri-commodities. Subsidiaries such as 3.0 Verse Limited and Ticker Data Limited add to its footprint in fintech data infrastructure. Though unlisted, the company\'s shares have drawn investor interest on the back of recurring revenue and scalability. Led by CEO Joseph Massey and a fairly diverse board, Ticker is known for system resilience, data quality and its positioning within India\'s evolving financial-information space.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', NULL, '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100053, 'Otis Elevator Co (India) Limited', 'otis-elevator-co-india-limited', 'images/company-logo/otis-elevator-co-india-limited.png', 39, 'Electric Equipment', 'INE099A01014', 'Otis Elevator', NULL, NULL, 'pre_ipo', NULL, '1953', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.otis.com/en/in/', NULL, 'Otis Elevator Company (India) Limited, incorporated in 1953, is the Indian arm of the global elevator major and is headquartered in Mumbai. The company manufactures and installs elevators, escalators and moving walkways in India, supported by a manufacturing facility in Bangalore.\n\nOtis holds the position of India\'s largest elevator company by portfolio, service reach and revenue, serving around 300 cities through a network of 97 service centres that operate round the clock to keep response times short.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '5', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100054, 'Versuni India Home Solutions Limited (formerly Philips Domestic Appliances India Limited)', 'philips-domestic-appliances-india-limited', 'images/company-logo/philips-domestic-appliances-india-limited.png', NULL, 'Household & Personal Products', 'INE0FO801019', 'Philips Domestic Appliances', NULL, NULL, 'pre_ipo', NULL, '2020', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.versuni.com/', NULL, 'Philips Domestic Appliances India Limited was set up on 17 July 2020 as a wholly owned subsidiary of Philips India Limited, taking over the parent\'s domestic-appliances business. That division had posted net revenue of ₹706 crore, net earnings of ₹11 crore and cash from operations of ₹134 crore in FY2020-21.\n\nThe company\'s product range covers coffee makers, home-care items and kitchen appliances, and it operates under the backing of Royal Philips of the Netherlands, one of the world\'s larger consumer-electronics manufacturers.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100055, 'IKF Finance', 'ikf-finance', 'images/company-logo/ikf-finance.png', 50, 'Finance - NBFC', 'INE859C01017', 'IKF Finance', NULL, NULL, 'pre_ipo', NULL, '1991', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.ikffinance.com/', NULL, 'IKF Finance Limited, established in 1991 and headquartered in Andhra Pradesh, is an NBFC focused on asset financing. It started out financing commercial vehicles and has since widened into cars, multi-utility vehicles, tractors, construction equipment and secured MSME loans. The company operates across nine states through more than 130 branches, serving small road-transport operators, first-time buyers, underserved communities and farmers.\n\nIKF Finance has grown its AUM past ₹2,000 crore, with a customer base exceeding 60,000. A 2022 co-lending tie-up with the Bank of India was meant to strengthen its MSME book and offer more cost-effective vehicle financing. The company counts Motilal Oswal Private Equity among its investors and carries credit ratings of A+ (Stable) from CARE Ratings and A (Stable) from IndiaBonds. Under founder-chairman VGK Prasad and managing director K. Vasumathi Devi, the company continues to emphasise ethical practices, transparency and customer service.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', NULL, NULL, '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100056, 'Bharat Nidhi Limited', 'bharat-nidhi-limited', 'images/company-logo/bharat-nidhi-limited.png', 50, 'Finance - NBFC', 'INE286F01016', 'Bharat Bank', NULL, NULL, 'pre_ipo', 'September', '1942', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Bharat Nidhi Limited, established on 21 September 1942 and headquartered in Delhi, is a private limited company engaged in distributing publications such as newspapers and magazines. It holds a significant shareholding in Bennett, Coleman and Co. Ltd. (BCCL), better known as The Times Group — publisher of the Times of India, India\'s largest English daily, and owner of Times Internet, which runs digital platforms including Magicbricks, Gaana and Dineout.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '5', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100057, 'Arohan Financial Services', 'arohan-financial-services', 'images/company-logo/arohan-financial-services.png', 50, 'Finance - NBFC', 'INE808K01017', 'Arohan Financial', NULL, NULL, 'pre_ipo', NULL, '2006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.arohan.in/', NULL, 'Arohan Financial Services Limited, headquartered in Kolkata and set up in 2006, is an NBFC-MFI within the Aavishkaar Group, built around expanding financial inclusion by offering credit, insurance and other products to low-income households, women borrowers and micro-enterprises that typically struggle to access formal banking.\n\nThe company runs a fairly large branch network spread across 18-plus states, using a joint-liability-group model to extend collateral-free loans, alongside digital lending through its Arohan Privilege platform. Its loan portfolio has grown past ₹6,000 crore, reaching millions of underserved customers, and the company is recognised for strong credit ratings and social-performance metrics — pairing sustainable business practices with a stated mission of empowering economically marginalised communities.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100058, 'Indofil Industries Ltd', 'indofil-industries-ltd', 'images/company-logo/indofil-industries-ltd.png', NULL, 'Chemicals', 'INE071I01016', 'Indofil Industries', NULL, NULL, 'pre_ipo', NULL, '1962', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.indofil.com/', NULL, 'Indofil Industries Ltd., incorporated in 1962 as a subsidiary of Rohm & Haas Co. of the USA and based in Thane, is now part of the K.K. Modi Group and holds a distinctive position in the SPCD market for specialised and performance chemicals used in agriculture. The company manufactures and distributes agrochemicals, speciality chemicals and performance chemicals in India, organised across three business segments — agrochemicals, speciality/performance chemicals, and investments.\n\nIts mancozeb formulations reach more than 60 countries through exports, and the company markets a range of insecticides, fungicides, bactericides, herbicides, acaricides, surfactants and plant-growth regulators domestically, built around what it calls a \"crop care\" philosophy. Beyond agriculture, Indofil also supplies speciality performance chemicals to the construction, paints and coatings, textile, leather and plastics industries, distributing largely through dealers and distributors.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100059, 'Merino Industries Limited', 'merino-industries-limited', 'images/company-logo/merino-industries-limited.png', NULL, 'Ceramics/Marble/Granite/Sanitaryware', 'INE662B01017', 'Merino Industries', NULL, NULL, 'pre_ipo', NULL, '1965', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.merinolaminates.com/', NULL, 'The Merino Group, incorporated in 1965 and headquartered in Kolkata, is India\'s largest manufacturer and exporter of laminates. Its manufacturing units are spread across Hapur (Uttar Pradesh), Rohad (Haryana), Dahej (Gujarat) and Hosur (Tamil Nadu), and the company sells into more than 60 countries while maintaining a presence across most Indian states.\n\nWith over 2,000 outlets and more than 4,000 dealers, Merino offers a fairly wide range of interior-solution products for offices, homes, commercial spaces and public areas.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '10', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100060, 'RoyalCare Super Speciality Hospital Limited', 'royalcare-super-speciality-hospital-limited', 'images/company-logo/royalcare-super-speciality-hospital-limited.png', NULL, 'Hospital & Healthcare Services', 'INE02C801010', 'Royalcare Super Speciality Hospital', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.royalcarehospital.in/', NULL, 'Royal Care Super Speciality Hospital Limited, established on 1 May 2015 in Coimbatore, Tamil Nadu, started out as a 50-bed facility and grew fairly quickly into a 750-bed hospital at Neelambur, with the first 300 beds opening in November 2016. It offers care across specialities including cardiology, neurology, oncology, nephrology, transplant units and emergency care.\n\nLed by Dr. K. Madeswaran (Chairman & Managing Director) along with Dr. K. Chockalingam and P. K. Alagesan, Royal Care has built its reputation around patient-centred care, modern medical technology and international quality benchmarks. Among its milestones, the hospital was one of the first in India to introduce bronchial thermoplasty for severe asthma and advanced dialysis technologies. JCI-accredited, it positions itself around delivering quality healthcare that stays broadly accessible and affordable.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100061, 'Veeda Clinical Research Limited (CRO)', 'veeda-clinical-research-limited-cro', 'images/company-logo/veeda-clinical-research-limited-cro.png', NULL, 'Medical Equipment/Supplies/Accessories', 'INE01HQ01026', 'Veeda Clinical Research', NULL, NULL, 'pre_ipo', NULL, '2004', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.veedacr.com/', NULL, 'Veeda Clinical Research Limited, established in 2004, is a contract research organisation (CRO) based in India that provides clinical research services to pharmaceutical and biotech companies worldwide. Its service range covers bioavailability and bioequivalence studies, phase I-IV clinical trials, clinical data management, pharmacovigilance and statistical analysis.\n\nBacked by modern facilities and alignment with international regulatory standards, Veeda positions itself around delivering high-quality, ethical research output, and it has built a reputation as a partner for drug development and regulatory submissions across global markets.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100062, 'Sun Drops Energia Limited', 'sun-drops-energia-limited', 'images/company-logo/sun-drops-energia-limited.png', 142, 'Other', 'INE0H1U01025', 'Sun Drops Energia', NULL, NULL, 'pre_ipo', NULL, '2019', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Sun Drops Energia Limited, headquartered in Gujarat and established in 2019, is the solar power arm of the KP Group, working across development, construction, ownership, operation and maintenance of solar, hybrid and energy-storage projects. It operates both as an Independent Power Producer and as a partner to Captive Power Producers, serving industrial and commercial customers.\n\nThe company has grown a solar and hybrid asset base across Gujarat and has moved into battery energy storage systems (BESS) as part of supporting India\'s clean-energy transition. As a subsidiary of KPI Green Energy Limited, Sun Drops Energia forms part of the group\'s broader renewable-energy expansion plans.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100063, 'Kineco Limited', 'kineco-limited', 'images/company-logo/kineco-limited.png', 142, 'Other', 'INE139Y01018', 'Kineco', NULL, NULL, 'pre_ipo', NULL, '1995', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.kinecogroup.com/', NULL, 'Kineco Limited was founded in 1995 by Shekhar Sardessai in Goa, starting out as a small manufacturer of fibreglass-reinforced plastic (FRP) industrial equipment. Since then, it has grown into one of India\'s leading composite-manufacturing companies, with capabilities spanning aerospace, defence, railways and industrial applications. Spread across three facilities totalling roughly 33,000 sq. m in Goa and employing over 400 people, Kineco handles design, development, prototyping and serial production using techniques including resin transfer moulding, vacuum bagging, autoclave curing, pultrusion, filament winding and smart resin infusion.\n\nA key milestone came in 2012 with a joint venture with US-based Kaman Aerospace Group — Kineco Kaman Composites India Pvt. Ltd. (KKCI) — focused on structural carbon- and glass-fibre components for aircraft, helicopters, UAVs and spacecraft. In 2025, Kineco bought out Kaman\'s remaining stake, making KKCI a wholly owned subsidiary now folded into its Aerospace & Defence business unit. The Goa facility carries global NADCAP accreditation across composites, NMMT, NDT and chemical processing, along with AS9100 Rev-D, ISO 9001/14001/45001 certifications and a ZED Gold rating, and has supplied components for programmes including ISRO\'s Chandrayaan-3 and Gaganyaan, and defence projects such as HAL\'s Light Combat Aircraft and Advanced Light Helicopter.\n\nIn March 2025, the Aerospace & Defence unit signed a multi-million-dollar contract with GKN Aerospace to supply lightweight composite components for business jets, adding to its international footprint. Kineco\'s Railways SBU, which is IRIS-certified, separately supplies coach interiors, aerodynamic fronts, toilet modules, pressure vessels, carbon-reinforced structural parts and turnkey rail interiors to national and international customers.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100064, 'Goodluck Defence And Aerospace Ltd', 'goodluck-defence-and-aerospace-ltd', 'images/company-logo/goodluck-defence-and-aerospace-ltd.png', NULL, 'Defence', 'INE0S7401019', 'Goodluck Defence', NULL, NULL, 'pre_ipo', NULL, '2023', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Goodluck Defence and Aerospace Ltd operates in the defence and aerospace space, working on solutions aimed at military and aerospace applications. The company positions itself around research, development and advanced technology, with a product and service range covering aircraft components, defence electronics and strategic systems.\n\nIt presents itself as a partner to government and defence organisations, with quality and precision as recurring themes in how it describes its role in shaping the defence and aerospace industries through its technology offerings and collaborations.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100065, 'A One Steels India Limited', 'a-one-steels-india-limited', 'images/company-logo/a-one-steels-india-limited.png', NULL, 'Steel & Iron Products', 'INE0OTC01025', 'A One Steels', NULL, NULL, 'pre_ipo', NULL, '2012', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.aonesteelgroup.com/', NULL, 'A One Steels India Limited, based in Bengaluru, is a backward-integrated steel manufacturer established in 2012 and converted into a public limited company in 2024. It runs manufacturing facilities across Karnataka and Andhra Pradesh, producing a range of steel products including TMT bars, long and flat steel products, HR and CR coils and pipes, sponge iron, MS billets, and value-added intermediates such as ferro silicon and met coke.\n\nWith operations spanning raw-material processing through to finished goods, the company emphasises operational efficiency, quality control and cost management. Its customer base sits largely in construction, infrastructure and industrial sectors, with a strong presence in South India and an expanding market reach.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100066, 'GKN Driveline India Limited', 'gkn-driveline-india-limited', 'images/company-logo/gkn-driveline-india-limited.png', NULL, 'Auto Ancillary', 'INE527A01014', 'GKN Driveline', NULL, NULL, 'pre_ipo', NULL, '1985', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.gkndriveline.com/', NULL, 'GKN Driveline (India) Limited was set up as a private limited company in July 1985, originally under the name GKN Driveshafts (India) Limited. Since 2003, it has worked alongside GKN Driveline International in Germany on technology collaboration, which gives the Indian entity access to a range of GKN\'s technology.\n\nThe company\'s core business is manufacturing and distributing driveshafts to original equipment manufacturers in the automotive sector.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100067, 'Mohan Meakin Limited', 'mohan-meakin-limited', 'images/company-logo/mohan-meakin-limited.png', NULL, 'Breweries & Distilleries', 'INE136D01018', 'Mohan Meakin', NULL, NULL, 'pre_ipo', NULL, '1934', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.mohanmeakin.com/', NULL, 'Mohan Meakin Limited, incorporated on 2 November 1934, is a longstanding conglomerate in alcoholic beverages — rum, whisky, beer, vodka and gin among them — as well as non-alcoholic products such as apple juice, mineral water and non-fruit vinegar. Widely regarded as a pioneer of India\'s liquor industry, the company has set up distilleries and breweries across several parts of the country and exports to markets including Germany, Russia, the US, Oman and the UAE.\n\nBeyond beverages, Mohan Meakin has diversified over the years into fruit juices, breakfast foods, cold storage, mineral water and a glass factory, broadening its business interests well past its original alcohol-focused roots.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '20', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100068, 'Kannur International Airport Limited', 'kannur-international-airport-limited', 'images/company-logo/kannur-international-airport-limited.png', 4, 'Airlines', 'INE02Y401013', 'Kannur International Airport', NULL, NULL, 'pre_ipo', NULL, '2009', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://kannurairport.aero/', NULL, 'Kannur International Airport Limited (KIAL) operates Kannur International Airport in Kerala as a public-private joint venture, opened in 2018 as part of the Indian government\'s push toward greater private-sector participation in airport development. Ownership sits with the Kerala state government alongside private investors including GVK Power and Infrastructure Limited and Federal Bank Limited.\n\nThe airport\'s terminal building is built to handle up to 1,800 passengers an hour, making it one of the larger airports in India by that measure. KIAL has also put some focus on environmental sustainability, including the use of renewable energy sources and eco-friendly operational practices.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100069, 'Kurlon Enterprise', 'kurlon-enterprise', 'images/company-logo/kurlon-enterprise.png', NULL, 'Household & Personal Products', 'INE387W01025', 'Kurlon Ent', NULL, NULL, 'pre_ipo', NULL, '2011', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.kurlon.com/', NULL, 'Kurl-on Limited is the holding company of Kurlon Enterprise, in which it holds an 85.06% stake. The Kurl-on story traces back to Ramesh Pai, who, during a trip to Germany, noticed high-end car seats made from rubberised coconut-coir fibre sourced from Sri Lanka. Recognising that India was among the world\'s largest coconut producers, Pai returned home to explore how the country\'s own coir husk could be put to better use — at the time, it was mostly used in cottage-industry retted-fabric production. That idea eventually became Karnataka Consumer Products Limited, later known as Kurl-on, built around Austrian technology for extracting and curling coir fibre into rope, and expanding from mattresses into cushions and mats.\n\nIn 2004, the company moved beyond sleep products into the broader home-comfort segment. Today, Kurl-on manufactures mattresses across 126 configurations, working with a pan-India network of more than 10,000 dealers, 72 branch and stock points, and nine manufacturing facilities spread across Karnataka, Odisha, Madhya Pradesh, Uttarakhand and Gujarat.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '25', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100070, 'Innov8 Workspaces India Limited', 'innov8-workspaces-india-limited', 'images/company-logo/innov8-workspaces-india-limited.png', NULL, 'Construction - Real Estate', 'INE1DBW01022', 'Innov8 Workspaces India', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://innov8.work/', NULL, 'Innov8 Workspaces India Limited, founded in 2015 by Dr. Ritesh Malik, runs a network of coworking spaces across India catering to startups, freelancers, SMEs and larger enterprises. Its centres are spread across major cities — Delhi NCR, Mumbai, Bengaluru, Pune, Hyderabad, Chennai and Ahmedabad — giving it a fairly wide footprint in the flexible-workspace segment.\n\nThe company builds its spaces around community and collaboration, with amenities such as high-speed internet, meeting rooms, event areas, lounges and breakout zones designed to combine functionality with aesthetics. Innov8 became part of OYO in 2019, which helped it scale further, and it\'s now recognised as one of the names that has helped make coworking a more mainstream, flexible option for businesses of different sizes.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100071, 'Zenith Leisure Holidays Limited', 'zenith-leisure-holidays-limited', 'images/company-logo/zenith-leisure-holidays-limited.png', NULL, 'Travel Services', 'INE0ETS01014', 'Zenith Holidays', NULL, NULL, 'pre_ipo', NULL, '2001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.zenithholidays.com/', NULL, 'Zenith Leisure Holidays Limited, headquartered in Kolkata, is a well-established Indian travel and tourism company with a presence spanning leisure travel, corporate travel including MICE (meetings, incentives, conferences and exhibitions), inbound tours, events and foreign-exchange services. Its holiday packages are built to be customisable, catering to individual travellers, groups, honeymooners, students, senior citizens and corporate clients.\n\nOver time, the company has widened its offerings beyond traditional tour operations into inbound travel, rewards programmes and event management, supported by a fairly broad branch network across India. It positions itself around a customer-first approach, aiming for end-to-end travel solutions built on service quality, reliability and value for money.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100072, 'Axles India Limited', 'axles-india-limited', 'images/company-logo/axles-india-limited.png', 142, 'Other', 'INE701C01011', 'Axles India', NULL, NULL, 'pre_ipo', NULL, '1982', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://axlesindia.com/', NULL, 'Axles India Limited, headquartered in Chennai and established in 1982, manufactures automotive components as a joint venture between TSF Investments Limited and Wheels India, with earlier technology tie-ups involving global names such as Eaton and Dana. Its core product is axle housings and related components for light, medium and heavy commercial vehicles, sold both domestically and overseas.\n\nManufacturing facilities in Sriperumbudur, Cheyyar and Jamshedpur give the company meaningful production capacity for axle housings. Its client list includes major OEMs such as Tata Motors, Ashok Leyland and Daimler India Commercial Vehicles, alongside export markets. Engineering expertise, quality certification and a focus on design validation and operational efficiency underpin its position in the automotive-components space.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100073, 'Hindustan Power Exchange Limited - HPX', 'hindustan-power-exchange-limited-hpx', 'images/company-logo/hindustan-power-exchange-limited-hpx.png', NULL, 'Power Generation/Distribution', 'INE07WD01012', 'HPX India', NULL, NULL, 'pre_ipo', 'April', '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.hpxindia.com/', NULL, 'Hindustan Power Exchange Limited (HPX), incorporated in April 2018, runs a platform for trading electrical energy in India, promoted by PTC India, the Bombay Stock Exchange and ICICI Bank. It began operations in July 2022 after receiving the required approvals from the Central Electricity Regulatory Commission, and its offerings include contingency contracts, green contingency contracts and renewable energy certificates, alongside weekly, monthly, long-duration and intra-day contract segments as the exchange has grown.\n\nTrading volumes have scaled quickly since launch — HPX crossed 2.5 billion units traded within eight months and 5 billion units within about eleven months — while onboarding more than 500 market participants and steadily building market share, particularly in the Term Ahead Market segment.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100074, 'Transline Technologies Limited', 'transline-technologies-limited', 'images/company-logo/transline-technologies-limited.png', 65, 'IT - Software', 'INE0OR401022', 'Transline Technologies', NULL, NULL, 'pre_ipo', NULL, '2001', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://translineindia.com/', NULL, 'Transline Technologies Limited, founded in 2001 and headquartered in New Delhi (CIN U72900DL2001PLC109496), works in advanced surveillance, biometrics, AI, IoT and IT-infrastructure solutions. With a workforce in the range of 200-300, the company\'s client list spans Indian Oil Corporation, Indian Railways, major banks, UIDAI and several police departments, across sectors including smart cities, railways, government, BFSI, oil & gas, logistics, healthcare, retail and telecom.\n\nIts offerings include AI-powered surveillance systems such as CheckCam and Smart CamStore, retail analytics through StorePulse, biometric identity solutions, and IT/data-centre infrastructure. The company holds certifications including ISO 9001, ISO 14001, ISO 27001, ISO 20000, ISO/IEC 27001:2013 and CMMI Level 5, reflecting its focus on quality, security and process maturity.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No');
INSERT IGNORE INTO `unlisted_stocks` (`UL_STOCKS_FINCODE`, `UL_STOCKS_COMPNAME`, `UL_STOCKS_SLUG`, `UL_STOCKS_LOGO_LINK`, `UL_STOCKS_IND_CODE`, `UL_STOCKS_INDUSTRY`, `UL_STOCKS_ISIN`, `UL_STOCKS_S_NAME`, `UL_STOCKS_CHAIRMAN`, `UL_STOCKS_MDIR`, `UL_STOCKS_CATEGORY`, `UL_STOCKS_INC_MONTH`, `UL_STOCKS_INC_YEAR`, `UL_STOCKS_STATUS`, `UL_STOCKS_ADD1`, `UL_STOCKS_ADD2`, `UL_STOCKS_ADD3`, `UL_STOCKS_CITY_NAME`, `UL_STOCKS_PINCODE`, `UL_STOCKS_STATE_NAME`, `UL_STOCKS_PHONE`, `UL_STOCKS_FAX_NO`, `UL_STOCKS_WEBSITE`, `UL_STOCKS_E_MAIL`, `UL_STOCKS_ABOUT`, `UL_STOCKS_INSERT_BY`, `UL_STOCKS_INSERT_TIME`, `UL_STOCKS_UPDATE_TIME`, `UL_STOCKS_COMP_RATING`, `UL_STOCKS_VALUATION_RATING`, `UL_STOCKS_LOT_SIZE`, `UL_STOCKS_ROFR_FLAG`, `UL_STOCKS_DEMAT_ACCOUNT_REQ`, `UL_STOCKS_BUY_SELL_FLAG`, `UL_STOCKS_COMPNAME_TYPE`, `UL_STOCKS_Qtr_Data_Publish`) VALUES
(100075, 'Lords Mark Industries', 'lords-mark-industries', 'images/company-logo/lords-mark-industries.png', NULL, 'Miscellaneous', 'INE0MPL01010', 'Lords Mark Industries', NULL, NULL, 'pre_ipo', NULL, '1998', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.lordsmark.com/', NULL, 'Lord\'s Mark Industries Limited, headquartered in Mumbai and operating for more than two decades, is a diversified conglomerate spanning Diagnostics and MedTech, Smart LED and Solar Technology, and Specialised Paper Manufacturing. In diagnostics, the company has developed products such as the E-Smart Clinic, a portable health kiosk built to run blood tests and connect rural patients with doctors, and it has partnered with IIT Bombay on AI-enabled sickle-cell testing and with BARC on cancer-detection kits.\n\nOn the renewable side, Lord\'s Mark has executed rooftop solar projects for government buildings and schools in Uttar Pradesh and Bihar, contributing to the Saubhagya Scheme aimed at bringing electricity to rural homes. It also has a longstanding position in computer continuous paper stationery printing, serving industries such as insurance and banking. The company\'s accolades include the Medical Device Excellence Award in 2023 and the Mid-Day Maharashtra Gaurav Award in 2024.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100076, 'Kanara Consumer Products Limited', 'kanara-consumer-products-limited', 'images/company-logo/kanara-consumer-products-limited.png', NULL, 'Household & Personal Products', 'INE781F01032', 'Kanara Consumer Products', NULL, NULL, 'pre_ipo', NULL, '1962', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.kurlon.com/', NULL, 'Kurl-on Limited, established in 1962 and headquartered in Bangalore, is a manufacturer of sleep solutions and home-comfort products in India, with a range spanning mattresses, pillows, furniture and home-textile products. The company puts a fair amount of weight on R&D, aiming for products that hold up on comfort, durability and quality, while also working to keep production efficient and limit environmental impact.\n\nCustomer service is another area the company emphasises, backed by a large network of retail outlets and distributors across India along with value-added services such as financing options and home delivery. Kurl-on has built strong customer relationships over the years and has picked up recognition for its performance and sustainability efforts within the Indian economy.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100077, 'Utkarsh Micro Finance Ltd - Utkarsh CoreInvest Ltd', 'utkarsh-micro-finance-ltd-utkarsh-coreinvest-ltd', 'images/company-logo/utkarsh-micro-finance-ltd-utkarsh-coreinvest-ltd.png', 50, 'Finance - NBFC', 'INE396P01012', 'Utkarsh Core Invest', NULL, NULL, 'pre_ipo', NULL, '1990', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.utkarshcoreinvest.com/', NULL, 'Utkarsh Micro Finance began operations in September 2009 in Varanasi, Uttar Pradesh, as the original microfinance arm of what is now a broader financial-services group, built around serving underserved and unbanked populations. It started life as an NBFC extending small loans under the Joint Liability Group model, focusing on low-income individuals and micro-entrepreneurs across rural and semi-urban parts of the Hindi heartland — Uttar Pradesh, Bihar, Madhya Pradesh and Uttarakhand among them.\n\nOver time, the company widened into micro-enterprise loans, housing loans, pension products and other retail lending, raising equity and debt capital from institutional investors to fund growth and financial-inclusion goals. In 2016, it received an RBI licence to set up a Small Finance Bank, leading to the formation of Utkarsh Small Finance Bank Limited as the microfinance business moved into broader banking. The holding entity was subsequently renamed Utkarsh CoreInvest Limited.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100078, 'Hindon Mercantile Limited', 'hindon-mercantile-limited', 'images/company-logo/hindon-mercantile-limited.png', 50, 'Finance - NBFC', 'INE08GI01012', 'Hindon Mercantile', NULL, NULL, 'pre_ipo', 'August', '1985', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://hindon.co/', NULL, 'Hindon Mercantile Limited (HML), founded on 14 August 1985 and headquartered in New Delhi, is a non-deposit-taking NBFC registered with the RBI, offering personal loans, business loans, equipment and machinery finance, loans against property, supply-chain finance and education loans.\n\nThrough its majority-held subsidiary Mufin Green Finance, HML has expanded into EV financing and the wider EV ecosystem. Led by promoters including Kapil Garg, the company leans on a technology-driven, omni-channel approach to make financing more accessible. It has shown fairly steady growth in recent years — raising equity capital, growing its AUM, and maintaining a solid capital adequacy ratio — while keeping a focus on sustainable finance.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100079, 'Goodluck Green Energy Ltd', 'goodluck-green-energy-ltd', 'images/company-logo/goodluck-green-energy-ltd.png', 83, 'Renewable Energy', 'INE14Z701011', 'Goodluck Green Energy', NULL, NULL, 'pre_ipo', 'January', '2024', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.goodluckgreen.com/', NULL, 'Goodluck Green Energy Limited was incorporated on 9 January 2024 and is headquartered at Plot No E-24, Udhyog Kunj, Ghaziabad, Uttar Pradesh (CIN U43299UP2024PLC195449), registered under the \"Electricity, Gas, Steam & Air Conditioning Supply\" sector. Though still at an early stage of operations, the company is part of the broader Goodluck India Limited group\'s move into clean energy, positioned to tap into India\'s shift toward green infrastructure.\r\n\r\nIn effect, Goodluck Green Energy gives the parent group a dedicated vehicle for its energy-supply and clean-infrastructure ambitions, built on the group\'s engineering background and a base in the Delhi-NCR manufacturing corridor.', '6', '2026-08-24 16:10:51', '2026-08-25 07:32:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100080, 'Fino Paytech Ltd.', 'fino-paytech-ltd', 'images/company-logo/fino-paytech-ltd.png', 157, 'Finance - Others', 'INE511I01011', 'Fino Paytech', NULL, NULL, 'pre_ipo', NULL, '2006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.finopaytech.com/', NULL, 'Fino Paytech, founded on 13 July 2006 and headquartered in Mumbai, is the parent company of Fino Payments Bank. It runs as a business-and-banking-technology platform paired with a wide services-delivery network, built to support end-to-end customer sourcing and servicing as an alternate banking channel.\n\nThe company is owned by a mix of international and Indian institutional investors, and it has positioned itself as a technology partner to micro-finance institutions, government bodies, banks and insurance companies, with a stated goal of meeting the financial-service needs of a wide customer base.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100081, 'Maverick Simulation Solutions Limited', 'maverick-simulation-solutions-limited', 'images/company-logo/maverick-simulation-solutions-limited.png', NULL, 'Hospital & Healthcare Services', 'INE1BEQ01014', 'Maverick Simulation', NULL, NULL, 'pre_ipo', 'September', '2023', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://mavericksimulation.com/', NULL, 'Maverick Simulation Solutions Limited, incorporated on 4 September 2023 and headquartered in Dwarka, New Delhi, is a med-tech company focused on designing, developing and manufacturing medical simulation and training equipment aimed at improving healthcare education and clinical skills training in India. Led by directors including Anuj Chahal, Kanika Chahal and Dr. Sunil Tomar, the company relies on in-house R&D to build a range of simulators — from basic task trainers and CPR models through to high-fidelity clinical simulators incorporating AI, AR and VR.\n\nThese products are used by medical, nursing and paramedical institutions to give students realistic, hands-on practice in a controlled setting, with the goal of reducing errors in patient care, and are deployed across a number of public and private training centres. The company has been putting meaningful investment into R&D, working with institutions such as AIIMS and the IITs, as it looks to build a stronger position in the growing med-tech simulation space.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100082, 'S3V Vascular Technologies Limited', 's3v-vascular-technologies-limited', 'images/company-logo/s3v-vascular-technologies-limited.png', NULL, 'Medical Equipment/Supplies/Accessories', 'INE0HGT01012', 'S3V Vascular', NULL, NULL, 'pre_ipo', NULL, '2011', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.s3vvascular.com/', NULL, 'S3V Vascular Technologies Limited, founded in 2011 and headquartered in Mysuru, Karnataka, develops, manufactures and markets minimally invasive cardiovascular, neurovascular and critical-care medical devices, including drug-eluting stents, PTCA balloon catheters, aspiration catheters and central venous catheters. Its stated goal is making advanced medical technology more affordable in India and reducing reliance on imported devices.\n\nThe company runs in-house R&D alongside integrated manufacturing, and is expanding into neurovascular care, including work on mechanical-thrombectomy kits for stroke treatment. S3V has drawn meaningful investment to scale up operations and build a modern manufacturing facility, reflecting ambitions that extend beyond the domestic market.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100083, 'Insolare Energy Limited', 'insolare-energy-limited', 'images/company-logo/insolare-energy-limited.png', 83, 'Renewable Energy', 'INE0TSJ01021', 'Insolare Energy', NULL, NULL, 'pre_ipo', NULL, '2008', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://insolare.com/', NULL, 'Insolare Energy Limited, founded around 2008-09 and headquartered in Ahmedabad, Gujarat, works as a technology-driven clean-energy solutions provider, primarily in solar EPC, with growing capabilities in hybrid energy systems, battery storage and green hydrogen. Over more than a decade, the company has built expertise in designing, executing and managing large-scale solar projects — ground-mounted plants, rooftop installations, canal-top systems, floating solar and solar-wind hybrid projects — across India.\r\n\r\nThe company\'s focus is on helping industries and infrastructure move toward lower-carbon energy, offering services from project design and engineering through to commissioning and maintenance. Backed by a team of engineers and technologists, Insolare has built up a fairly sizeable project portfolio and continues to invest in newer solar technologies and green-fuel solutions as part of India\'s broader net-zero push.', '6', '2026-08-24 16:10:51', '2026-08-25 07:35:31', '3', '3', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100084, 'A V Thomas and Co Limited', 'a-v-thomas-and-co-limited', 'images/company-logo/a-v-thomas-and-co-limited.png', NULL, 'Tea/Coffee', 'INE944K01010', 'AV Thomas', NULL, NULL, 'pre_ipo', NULL, '1932', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.avthomas.in/', NULL, 'A.V. Thomas & Co. Limited (AVT), established in 1932 and headquartered in Cochin, is a longstanding agribusiness company involved in producing, processing and exporting a range of agricultural products. Its modern processing facility supports exports of spices, fruits and vegetables to more than 50 countries, with products valued for taste, quality and nutrition.\n\nThe company has taken up several initiatives aimed at cutting its environmental footprint — renewable energy adoption, waste recycling and more efficient production processes among them. AVT also puts resources into community development in the areas it operates, including local employment and investment in education and healthcare programmes.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '5', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100085, 'Solar91 Cleantech Limited IPO', 'solar91-cleantech-limited-ipo', 'images/company-logo/solar91-cleantech-limited-ipo.png', NULL, 'Power Generation/Distribution', 'INE0U5I01016', 'Solar91 Cleantech', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.solar91.com/', NULL, 'Solar91 Cleantech Limited, incorporated in 2015, provides EPC solar-energy solutions to commercial and industrial clients aimed at cutting their power costs through renewables. Its offerings span rooftop solar for industrial, commercial and residential use, open-access and group-captive models, agro-PV, and distributed solar investment options.\n\nThe company has also moved into developing projects under the Independent Power Producer model, including initiatives under the PM Kusum scheme aimed at solarising agricultural power feeders. Solar91 has picked up recognition as an industry leader in Rajasthan and more broadly in the Commercial and Industrial Solar PV segment, with its business built around three segments — EPC services, IPP projects, and O&M services for solar installations.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100086, 'Lakeshore Hospital and Research Centre Limited', 'lakeshore-hospital-and-research-centre-limited', 'images/company-logo/lakeshore-hospital-and-research-centre-limited.png', NULL, 'Hospital & Healthcare Services', 'INE01TI01010', 'Lakeshore Hospital', NULL, NULL, 'pre_ipo', NULL, '1996', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.vpslakeshore.com/', NULL, 'Lakeshore Hospital And Research Centre Limited, known as VPS Lakeshore, was founded on 4 April 1996 and is registered as a public, non-government company with the Registrar of Companies in Ernakulam. It ranks among Kerala\'s largest independent multi-specialty hospitals, built around clinical treatment, research and medical education.\n\nOver the years the hospital has established itself through various clinical programmes, modern treatment options and diagnostic services, positioning itself as a healthcare destination for patients from India and beyond — with a stated mission of making healthcare accessible to all.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100087, 'Greenzo Energy India Limited', 'greenzo-energy-india-limited', 'images/company-logo/greenzo-energy-india-limited.png', NULL, 'Power Generation/Distribution', 'INE0OA401013', 'Greenzo Energy', NULL, NULL, 'pre_ipo', NULL, '2022', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://greenzoenergyindia.com/', NULL, 'Greenzo Energy India Limited works in the renewable energy sector, with a particular focus on green hydrogen. The company develops, owns and operates infrastructure for renewables and green hydrogen, aimed at delivering zero-emission energy services.\n\nIts approach leans toward pragmatic, cost-effective solutions, executing turnkey renewable energy projects globally using current technologies — part of a broader push toward sustainable, commercially viable hydrogen production to meet rising clean-energy demand.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100088, 'Honeywell Electrical Devices and Systems India Limited', 'honeywell-electrical-devices-and-systems-india-limited', 'images/company-logo/honeywell-electrical-devices-and-systems-india-limited.png', 39, 'Electric Equipment', 'INE848Y01014', 'Honeywell Electrical Devices and Systems', NULL, NULL, 'pre_ipo', NULL, '1984', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Honeywell Electrical Devices and Systems India Limited (HEDSI), a subsidiary of Honeywell International, provides electrical solutions and systems across residential, commercial and industrial markets in India. Its product range includes wiring devices, lighting-control systems and electrical safety equipment aimed at improving efficiency, safety and automation in electrical infrastructure.\n\nDrawing on Honeywell\'s global resources and expertise, HEDSI focuses on innovation and sustainable practices as it develops products for India\'s electrical and automation landscape, alongside a customer-centric approach to service and ongoing improvement.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '10', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100089, 'Berar Finance Limited', 'berar-finance-limited', 'images/company-logo/berar-finance-limited.png', 50, 'Finance - NBFC', 'INE998Y01017', 'Berar Finance', NULL, NULL, 'pre_ipo', NULL, '1990', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.berarfinance.com/', NULL, 'Berar Finance Limited, based in Nagpur and established in 1990, is an NBFC known primarily for two-wheeler financing across Central and Western India. Over time it has broadened into vehicle refinance, used-car loans, personal loans and secured products such as loans against property for small businesses.\n\nThe company\'s customer base sits largely in semi-urban and rural areas, aimed at improving credit access for underserved segments. Berar Finance has built out a fairly wide branch network across states and is among the relatively small number of NBFCs in India licensed to accept public deposits — a marker of its established standing in the sector.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '4', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100090, 'Bootes Impex Tech Ltd.', 'bootes-impex-tech-ltd', 'images/company-logo/bootes-impex-tech-ltd.png', NULL, 'Engineering - Construction', 'INE0U3P01016', 'Bootes Impex Tech', NULL, NULL, 'pre_ipo', NULL, '2021', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://bootes.in/', NULL, 'Bootes Impex Tech Ltd, incorporated on 4 March 2021 and headquartered in Gurugram, Haryana, positions itself as India\'s first Net-Zero construction company, working on eco-friendly infrastructure aligned with the country\'s 2070 carbon-neutral target. As a public limited company, it offers end-to-end Design, Build, Finance, Operate & Transfer (DBFOT) services across sectors such as museums, libraries, hospitals, hotels, universities, PPPs and land-development projects.\n\nThe company builds around technologies including renewable energy (solar and wind), hydronic systems, zero liquid discharge, zero waste, electrified HVAC and sustainable materials, which it says can cut operating costs by up to 75% and carbon emissions by up to 80%.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100091, 'Ring Plus Aqua Limited', 'ring-plus-aqua-limited', 'images/company-logo/ring-plus-aqua-limited.png', NULL, 'Auto Ancillary', 'INE093H01012', 'Ring Plus', NULL, NULL, 'pre_ipo', NULL, '1984', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://ringplusaqua.com/', NULL, 'Ring Plus Aqua Limited, incorporated in 1984, manufactures automotive and engineering products including starter gears, water-pump bearings, flexible plates and machined components. The company runs its operations out of Nashik, with a corporate office in Mumbai, and has built a fairly long track record supplying both auto and non-auto industries globally.\n\nManufacturing technology is a stated priority, with the company leaning on newer techniques to lift productivity and process speed. On the logistics side, RPAL has years of experience exporting to Europe, the US, South America, Japan, China, South East Asia and Australia, with its components used in tractors, light and heavy commercial vehicles, and passenger vehicles.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '100', 'No', 'NSDL', 'Yes', 'unlisted', 'No'),
(100092, 'B9 Beverages Limited - Bira', 'b9-beverages-limited-bira', 'images/company-logo/b9-beverages-limited-bira.png', NULL, 'Breweries & Distilleries', 'INE833U01014', 'Bira', NULL, NULL, 'pre_ipo', NULL, '2015', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://bira91.com/', NULL, 'B9 Beverages Limited, incorporated in 2015 and headquartered in New Delhi, is the company behind the Bira 91 beer brand, which has built a fairly strong following among urban millennials on the back of its distinctive branding, taste and draft-beer network. The beer itself is brewed from wheat, barley and hops, and comes in formats including 330ml and 650ml bottles and 500ml cans. The entity was originally registered under the name Divya Jyoti Coaching Institute Private Limited before becoming B9 Beverages.\n\nThe company now runs four breweries in India, producing a range of beer styles — light beer, strong ale, boom strong, classic beers, white ale, blonde lager and more. Interestingly, its first brewing unit was actually located in the Flanders region of Belgium, where a craft distillery made the beer using ingredients sourced from the Himalayas, France, Belgium and Bavarian farms before it was imported into India. Once the brand found early success, production shifted to India using the same ingredient sourcing. Bira 91 expanded to New York in 2017 to launch its US push, and moved into the Asia-Pacific market via Singapore in 2018.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100093, 'KLM Axiva Finvest Limited', 'klm-axiva-finvest-limited', 'images/company-logo/klm-axiva-finvest-limited.png', 49, 'Finance - Investment', 'INE01I501011', 'KLM Axiva Finvest', NULL, NULL, 'pre_ipo', NULL, '1997', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.klmaxiva.com/', NULL, 'KLM Axiva Finvest is an India-based financial-services company offering a range of investment and financial solutions, including mutual fund distribution, wealth management and advisory services aimed at helping individual investors manage their portfolios.\n\nThe company works with established industry partners to give clients access to reliable financial products, positioning its approach around transparency, efficiency and customer-focused service intended to support long-term financial growth for both individuals and corporate clients.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100094, 'Inkel Limited', 'inkel-limited', 'images/company-logo/inkel-limited.png', 29, 'Infrastructure', 'INE308U01017', 'Inkel', NULL, NULL, 'pre_ipo', NULL, '2007', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://inkel.in/', NULL, 'INKEL Limited — short for Infrastructures Kerala Limited — is a Kochi-headquartered infrastructure company set up in 2007 as a public-private-partnership initiative promoted by the Government of Kerala, alongside private investors, NRIs and the general public. The state government holds roughly a 29.6% stake, with the structure designed to channel both public and private capital, along with professional expertise, into infrastructure development across Kerala.\n\nThe company operates as a project management consultant (PMC) and EPC (engineering, procurement and construction) contractor, delivering projects end-to-end from concept through commissioning. Its core project types include super-speciality hospitals, roads, bridges, conservation work, and institutional and industrial buildings, largely for Kerala government departments and agencies such as the Department of Health and Family Welfare, the Department of Tourism, KSIDC, KIIFB, KSEB and the National Health Mission.\n\nSince 2016, INKEL has also built out a renewable energy division, starting with solar street lighting for road projects and expanding into rooftop and ground-mounted solar EPC, feasibility studies, DPR preparation, and O&M services — the company holds government accreditation to implement renewable energy projects for local self-government bodies and the Department of Co-operation. It also runs joint ventures such as INKEL-EKK Roads for a state-highway rehabilitation project in Kottayam and Thiruvananthapuram, and INKES Trade Centre for commercial real estate. P. Rajeeve serves as Chairman and Dr. K. Ellangovan as Managing Director. For FY24, the company reported revenue of around ₹79 crore and profit after tax of about ₹16 crore.', '6', '2026-08-24 16:10:51', '2026-08-25 07:25:19', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100095, 'National E Repository Limited - NeRL', 'national-e-repository-limited-nerl', 'images/company-logo/national-e-repository-limited-nerl.png', 142, 'Other', 'INE878X01013', 'NeRL', NULL, NULL, 'pre_ipo', 'February', '2017', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.nerlindia.com/', NULL, 'National E-Repository Limited (NeRL), incorporated in February 2017, is a nationally recognised warehousing repository backed by institutions including NCDEX, NABARD, SBI and ICICI Bank. Operating under the Warehousing Development and Regulatory Authority (WDRA), it runs a fully electronic platform for creating, storing, transferring, pledging and auctioning electronic Warehouse Receipts (eWRs), both negotiable and non-negotiable.\n\nNeRL began operations in September 2017 with the goal of improving rural liquidity, building fiduciary trust among stakeholders, and reducing issues such as forgery, duplication and delays that come with physical receipts. By combining technology with institutional backing, the company aims to modernise commodity financing and warehousing for farmers, traders, processors and financial institutions across India.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '4', '2000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100096, 'Urban Tots - Deepak Houseware and Toys Pvt Ltd', 'urban-tots-deepak-houseware-and-toys-pvt-ltd', 'images/company-logo/urban-tots-deepak-houseware-and-toys-pvt-ltd.png', 155, 'e-Commerce', 'INE0MQ801018', 'Urban Tots', NULL, NULL, 'pre_ipo', NULL, '2020', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Deepak Houseware and Toys (DH&T), operating under the Urban Tots brand, started operations in August 2021 and is headquartered under ROC Jaipur. The company manufactures and sells toys — plastic and electronic among them — and counts itself among the earlier entrants into domestic toy manufacturing.\n\nProduction runs out of a plant in Rajasthan equipped with around 60 pieces of machinery, and the company has been working to add wooden and metallic toys to broaden its manufacturing base. It has also benefited from a 5% interest-payment rebate offered by the Rajasthan state government under the DIC scheme, aimed at boosting local employment. Urban Tots has signed 18 exclusive distribution deals with names including FirstCry, DMart, VMart, Hamleys and Reliance, and its products are also sold online through platforms such as Amazon and Flipkart.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '2000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100097, 'Martin and Harris Laboratories Limited', 'martin-and-harris-laboratories-limited', 'images/company-logo/martin-and-harris-laboratories-limited.png', NULL, 'Chemicals', 'INE03VV01015', 'Martin and Harris Lab', NULL, NULL, 'pre_ipo', NULL, '1996', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://martinharrislabs.com/', NULL, 'Martin and Harris Laboratories Ltd, incorporated in 1996 and based in Gurgaon, is a pharmaceutical company and manufacturer of botanical products, operating as part of the Apeejay Group — one of India\'s oldest and largest business conglomerates. Alongside its core pharma business, the company also invests across mutual funds, listed shares and unlisted shares as part of its broader financial activities.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '10', 'No', 'NSDL', 'Yes', 'unlisted', 'No'),
(100098, 'Maharashtra Knowledge Corporation Ltd - MKCL', 'maharashtra-knowledge-corporation-ltd-mkcl', 'images/company-logo/maharashtra-knowledge-corporation-ltd-mkcl.png', NULL, 'Educational Institutions', 'INE03KR01016', 'MKCL', NULL, NULL, 'pre_ipo', NULL, '1956', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.mkcl.org/', NULL, 'Maharashtra Knowledge Corporation Limited (MKCL), set up under the Companies Act 1956 and headquartered in Pune, began operations in April 2002 with backing from the Department of Higher and Technical Education, Government of Maharashtra. The company\'s core focus is bringing information technology into education in a more integrated, universal way, offering print-based and CD-based self-study, web-based collaborative e-learning, and classroom-based learning.\n\nIts product and service range covers infrastructure development, e-content creation, educational and general e-governance, e-learning technology, learning-management systems and online assessment systems. Original equity investors include the Government of Maharashtra, eleven state universities, and a mix of educational, community, IT and non-IT organisations. MKCL\'s channel-partner network of Authorised Learning Centres has been set up by small and medium IT businesses and educational institutions across Maharashtra, spanning metropolitan, urban, semi-urban, rural, tribal and mountainous districts.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100099, 'PolicyX.com Insurance Web Aggregator Pvt Ltd', 'policyx-com-insurance-web-aggregator-pvt-ltd', 'images/company-logo/policyx-com-insurance-web-aggregator-pvt-ltd.png', NULL, 'Insurance', 'INE0NS801023', 'PolicyX', NULL, NULL, 'pre_ipo', NULL, '2013', '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.policyx.com/', NULL, 'PolicyX.com is an IRDA-approved insurance comparison platform built to help consumers compare and buy health, life and investment plans from leading Indian insurers. The company runs with a team of over 300 professionals and has built a reputation for offering guidance to a large number of Indian customers each year — the site drew over 8.2 million visitors in FY2020, with more than 80% of customers renewing policies annually.\n\nPolicyX.com works with more than 24 insurers and uses algorithm-driven matching to help users find suitable plans, backed by instant quotes, cash-flow charts, videos and infographics generated quickly. The company positions its goal as becoming India\'s most trusted insurance portal, built around fast, transparent and competitively priced insurance guidance.', '6', '2026-08-24 16:10:51', '2026-09-07 08:56:16', '5', '5', '10000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100100, 'Apollo Green Energy Ltd', 'apollo-green-energy-ltd', 'images/company-logo/apollo-green-energy-ltd.png', NULL, 'Power Generation/Distribution', 'INE838A01015', 'Apollo Green Energy', NULL, NULL, 'pre_ipo', NULL, '1994', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Apollo Green Energy Limited operates in the renewable-energy space, with its work centred on clean-energy technologies and services aimed at cutting environmental impact — spanning areas such as solar, wind and biomass energy. The company\'s broader positioning is around supporting the shift toward renewable resources, helping industries and communities reduce their carbon footprint.\n\nIts activities appear to cover developing, installing and maintaining energy systems for both large industrial applications and smaller, community-level projects, with a focus on combining current technology with sustainable practices to support energy resilience. This positions Apollo Green Energy as part of the broader push toward a greener economy and rising demand for renewable-energy solutions.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100101, 'HVR Solar Private Limited', 'hvr-solar-private-limited', 'images/company-logo/hvr-solar-private-limited.png', 142, 'Other', 'INE1NDM01010', 'HVR Solar', NULL, NULL, 'pre_ipo', NULL, '2016', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://hvrsolar.com/', NULL, 'HVR Solar Private Limited, established in 2016, manufactures solar photovoltaic modules, energy-storage solutions and solar power-system components out of its facilities in Sonipat, Haryana, serving residential, commercial, industrial and utility-scale customers. Its product line covers high-efficiency solar PV modules, batteries, solar street lighting, solar water-pumping systems and other clean-energy products.\n\nThe company leans on a mix of manufacturing process, quality-assurance systems and ongoing R&D to keep its solar offerings reliable and reasonably priced, and it also provides EPC services for solar projects, giving customers end-to-end support. As India\'s push toward sustainable development continues, HVR Solar has kept expanding its manufacturing capacity and technical capability, positioning itself as a contributor to the country\'s shift toward a greener, more energy-efficient future.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100102, 'Empire Spices and Foods Limited', 'empire-spices-and-foods-limited', 'images/company-logo/empire-spices-and-foods-limited.png', NULL, 'Consumer Food', 'INE041101010', 'Empire Spices and Foods', NULL, NULL, 'pre_ipo', NULL, '1994', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.rambandhu.com/', NULL, 'Empire Spices and Food Limited, founded in 1994, produces and sells pickle masala, vegetable pickles, masala papad, Indian spices, snacking pickle masala and garam podi, with its production facility based in Mumbai, Maharashtra. The company\'s roots go back to a small shop in Nashik, where the spice blends made there quickly gained a following, prompting the move to a dedicated manufacturing facility to keep up with demand.\n\nThat early success laid the groundwork for the well-known spice brand Ram Bandhu Masale, whose reputation and demand gradually spread to other cities across Maharashtra.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '5', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100103, 'Resins and Plastics Limited', 'resins-and-plastics-limited', 'images/company-logo/resins-and-plastics-limited.png', NULL, 'Chemicals', 'INE422F01017', 'Resins and Plastic', NULL, NULL, 'pre_ipo', NULL, '1961', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://resplast.com/', NULL, 'Resins and Plastics Ltd. (RPL), operating since 1971, manufactures a range of resins — Alkyd, Epoxies, Foundry, Ketonic and Phenolic among them — several of which serve as import substitutes. These synthetic resins find use across adhesives, coatings, dyes and pigments, insulating varnishes, wire enamels, lamination, construction, cosmetics, textiles and foundries, with the company manufacturing and marketing largely within India.\n\nStatutory approval for increased production received in FY21 opened up room to expand market reach and lift output and sales. RPL has built a reputation as a notable exporter of synthetic resins to coatings and printable-ink producers in neighbouring countries, with plans to grow its international presence further. Headquartered in Mumbai, the company runs two of its three manufacturing facilities near shipping ports — in Taloja, Maharashtra, and Ankleshwar, Gujarat.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100104, 'India Carbon Limited', 'india-carbon-limited', 'images/company-logo/india-carbon-limited.png', NULL, 'Chemicals', 'INE743B01015', 'India Carbon', NULL, NULL, 'pre_ipo', NULL, '1987', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.indiacarbonltd.com/', NULL, 'India Carbon Limited (ICL), established in 1987 and headquartered in Kolkata, is a leading producer of Calcined Petroleum Coke (CPC) in India, running a production facility with installed capacity of over 250,000 MT a year. The company\'s production process is designed to meet strict Indian emission norms, and the CPC it produces is used across industries including aluminium, steel, titanium dioxide and battery manufacturing.\n\nICL has taken up several steps to reduce its environmental footprint — renewable energy adoption, waste recycling and more efficient production among them — alongside value-added services such as logistics, technical support and customised client solutions, which have helped it build strong customer relationships and stay competitive in its market.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100105, 'Spray Engineering Devices Limited', 'spray-engineering-devices-limited', 'images/company-logo/spray-engineering-devices-limited.png', NULL, 'Engineering - Industrial Equipments', 'INE528I01015', 'Spray Engineering Devices', NULL, NULL, 'pre_ipo', NULL, '2004', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.sprayengineering.com/', NULL, 'Spray Engineering Devices Limited (SEDL) designs and manufactures equipment and systems for the sugar and process industries, positioning itself around sustainable solutions that improve efficiency and productivity. Its product range covers energy-efficient evaporators, condensers, heat exchangers and crystallisers, tailored to specific client requirements.\n\nSEDL puts emphasis on customised engineering that keeps environmental impact and operating costs down, backed by ongoing R&D aimed at keeping its technology current. That focus has helped the company build a reputation serving clients across sectors globally with what it positions as reliable, up-to-date engineering solutions.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100106, 'HCIN Network Pvt Ltd', 'hcin-network-pvt-ltd', 'images/company-logo/hcin-network-pvt-ltd.png', NULL, 'Telecom-Infrastructure', 'INE0U7Y01027', 'HCIN Network', NULL, NULL, 'pre_ipo', NULL, '2019', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.hicomindia.com/', NULL, 'HCIN Network Private Limited, founded in 2019, works in telecom infrastructure solutions, offering IT consulting and outsourcing services centred on developing and maintaining communication networks. The company has grown to a team of over 50 employees under founders Shalini Sharma and Vikas Sharma, who lead its push into advanced network solutions.\n\nHCIN has also grown through acquisition — including the purchase of a Computer Maintenance Agency — as part of expanding its IT-infrastructure service offerings.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '475', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100107, 'Anugraha Valve Castings Limited', 'anugraha-valve-castings-limited', 'images/company-logo/anugraha-valve-castings-limited.png', NULL, 'Castings/Forgings', 'INE629Z01015', 'Anugraha Valve Castings', NULL, NULL, 'pre_ipo', 'August', '1992', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.anugrahavalvecastings.com/', NULL, 'Anugraha Valve Castings Limited, a steel foundry based in Coimbatore, was established in August 1992 and specialises in manufacturing and exporting industrial valve castings ranging from 0.5\" to 32\", in both raw and fully machined form, serving the engineering, petroleum, oil & refinery, chemical and gas sectors worldwide.\n\nThe company runs four foundries and at least one modern machine shop across more than 26,945 sq. m, with annual capacity of around 15,000 MT. Quality control relies on equipment including induction furnaces ranging from 350 to 5,000 kg, hydrostatic test rigs, radiography, and a fully equipped lab with spectrometers and tensile, hardness and impact testing systems. Operations run on SAP ECC 6.x (implemented via Wipro), supported by MAGMA6 simulation software for casting optimisation.\n\nAnugraha holds certifications including ISO 9001:2015, ISO 14001:2015 and ISO 45001:2018, along with approvals under OHSAS 18001, PED, AD 2000-Merkblatt W0, and marine and oil-and-gas classification standards such as DNV-GL, ABS, RINA and NORSOK.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100108, 'Maxvalue Credits And Investments Ltd', 'maxvalue-credits-and-investments-ltd', 'images/company-logo/maxvalue-credits-and-investments-ltd.png', 50, 'Finance - NBFC', 'INE040401023', 'Maxvalue Credits And Investments', NULL, NULL, 'pre_ipo', NULL, '1995', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'MaxValue Credits & Investments Ltd. is an NBFC built around offering affordable financial services, with a particular emphasis on microfinance, gold loans and auto loans. It operates across Andhra Pradesh, Kerala and Karnataka, run by a team with backgrounds spanning various financial-services disciplines.\n\nThe company frames its mission around building close, lasting relationships with clients and offering non-banking financial expertise, backed by its scale, to help customers move toward financial independence and pursue their broader goals.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '5000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100109, 'NCL Buildtek Limited', 'ncl-buildtek-limited', 'images/company-logo/ncl-buildtek-limited.png', 155, 'e-Commerce', 'INE243S01010', 'NCL Buildtek', NULL, NULL, 'pre_ipo', NULL, '1986', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.nclbuildtek.com/', NULL, 'NCL Buildtek Ltd., incorporated in 1986 and part of the NCL Group, manufactures building products including plasters, doors, windows, paints, skim coats and steel profiles. Formerly known as NCL Alltek and Seccolor Ltd., the company was the first in India to manufacture putty and remains the sole Indian licence holder for ICP plasters.\n\nIts product range spans emulsion and textured paints, putty, cement-based products such as tile adhesives, mortars and plasters, pre-painted steel doors, windows, partitions and glazing, fly-ash bricks, and uPVC and ABS door and window fabrication. NCL Buildtek runs manufacturing units across 11 locations spread over several Indian states.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100110, 'ICL Fincorp Limited', 'icl-fincorp-limited', 'images/company-logo/icl-fincorp-limited.png', 50, 'Finance - NBFC', 'INE01CY01013', 'ICL Fincorp', NULL, NULL, 'pre_ipo', NULL, '1991', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.iclfincorp.com/', NULL, 'ICL Fincorp Limited, established in 1991 as Irinjalakuda Credits & Leasing Company Limited before being renamed on 8 May 2016, is an RBI-approved NBFC offering a range of financial services in India. Its offerings include debenture products, travel and tourism services, insurance, money transfer, foreign exchange, gold loans, business loans, hypothecation loans, property loans, car loans, hire-purchase loans and home-appliance loans.\n\nThe company\'s branch network across Kerala, Tamil Nadu, Telangana, Andhra Pradesh and Karnataka grew from 163 to 188 branches, including four branches under its subsidiary Salem Erode Investments Limited.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100111, 'Gamma Rotors Limited', 'gamma-rotors-limited', 'images/company-logo/gamma-rotors-limited.png', 142, 'Other', 'INE1VD201014', 'Gamma Rotors', NULL, NULL, 'pre_ipo', NULL, '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.gammarotors.com/', NULL, 'Gamma Rotors Limited, established in 2018 and headquartered in Noida, Uttar Pradesh, is an Indian drone and aerospace company working on the design, development and manufacture of advanced UAVs and defence-oriented drone systems. Its product range covers surveillance drones, logistics drones, custom UAV platforms, aerial inspection solutions and Air Remote Controlled Weapon Systems (ARCWS), serving defence, security, industrial and infrastructure customers with an emphasis on indigenous development under the \"Make in India\" push.\n\nThe company has built a name around integrating AI-enabled systems, aerial mapping, autonomous operation and additive manufacturing into its drones, aimed at improving performance while shortening production timelines. R&D investment has gone toward lightweight, high-performance UAV platforms capable of working in demanding conditions, supporting use cases from surveillance and reconnaissance to payload delivery and infrastructure monitoring. With a focus on technological self-reliance and defence modernisation, Gamma Rotors has been positioning itself as a notable name within India\'s growing drone and aerospace sector.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100112, 'The Ramaraju Surgical Cotton Mills Ltd', 'the-ramaraju-surgical-cotton-mills-ltd', 'images/company-logo/the-ramaraju-surgical-cotton-mills-ltd.png', NULL, 'Textile', 'INE328E01027', 'Ramaraju Surgical Cotton', NULL, NULL, 'pre_ipo', NULL, '1939', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'http://www.ramarajusurgical.com/', NULL, 'The Ramaraju Surgical Cotton Mills Ltd., originally called The Surgical Cotton Mills Ltd. before its name changed in June 1943, is part of the Ramco Group and, alongside the wider group\'s cement, roofing and construction business, manufactures cotton and specialised yarns. Its wound-care range includes absorbent cotton wool, cotton wool balls, zigzag-pleated cotton wool and absorbent gauze for dressing wounds, as well as cotton wool for cleaning and applying medication.\n\nThe mills were set up in Rajapalayam, Tamil Nadu, in 1939 to take advantage of locally grown cotton, following the 1935 establishment of Rajapalayam Mills Ltd. — together, the two played a meaningful part in shifting the region from an agrarian to a more industrial economy. The company is one of the primary manufacturers of absorbent cotton, gauze, bandages and related wound-care supplies in South India, turning out about 1.5 million square metres of bandage and gauze products and roughly 125 tonnes of medical-grade bleached cotton every month.\n\nOver time, the business has also expanded into spinning and weaving, producing cotton yarn and fine textiles used for shirting, bed linen and Jacquard fabric — with monthly output running to close to 400 tonnes of open-end yarn and a similar amount of superfine-count ring-spun yarn.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '50', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100113, 'Quality Enviro Engineers Private Limited', 'quality-enviro-engineers-private-limited', 'images/company-logo/quality-enviro-engineers-private-limited.png', 42, 'Engineering', 'INE0V2L01016', 'Quality Enviro', NULL, NULL, 'pre_ipo', NULL, '2016', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.qualityenviroengg.com/', NULL, 'Quality Enviro Engineers Private Limited works in environmental engineering, offering services across wastewater treatment, air pollution control, solid waste management and environmental impact assessments, built around the goal of improving environmental quality and supporting sustainable development.\n\nThe company\'s team of engineers and environmental scientists draws on current technology and practices to deliver solutions that stay compliant and cost-effective for clients across different industries, with quality, community health and safety positioned as core priorities. That focus has helped it build up a growing project portfolio and a reputation in environmental stewardship.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '1250', 'No', 'Both', 'Yes', 'unlisted', 'No');
INSERT IGNORE INTO `unlisted_stocks` (`UL_STOCKS_FINCODE`, `UL_STOCKS_COMPNAME`, `UL_STOCKS_SLUG`, `UL_STOCKS_LOGO_LINK`, `UL_STOCKS_IND_CODE`, `UL_STOCKS_INDUSTRY`, `UL_STOCKS_ISIN`, `UL_STOCKS_S_NAME`, `UL_STOCKS_CHAIRMAN`, `UL_STOCKS_MDIR`, `UL_STOCKS_CATEGORY`, `UL_STOCKS_INC_MONTH`, `UL_STOCKS_INC_YEAR`, `UL_STOCKS_STATUS`, `UL_STOCKS_ADD1`, `UL_STOCKS_ADD2`, `UL_STOCKS_ADD3`, `UL_STOCKS_CITY_NAME`, `UL_STOCKS_PINCODE`, `UL_STOCKS_STATE_NAME`, `UL_STOCKS_PHONE`, `UL_STOCKS_FAX_NO`, `UL_STOCKS_WEBSITE`, `UL_STOCKS_E_MAIL`, `UL_STOCKS_ABOUT`, `UL_STOCKS_INSERT_BY`, `UL_STOCKS_INSERT_TIME`, `UL_STOCKS_UPDATE_TIME`, `UL_STOCKS_COMP_RATING`, `UL_STOCKS_VALUATION_RATING`, `UL_STOCKS_LOT_SIZE`, `UL_STOCKS_ROFR_FLAG`, `UL_STOCKS_DEMAT_ACCOUNT_REQ`, `UL_STOCKS_BUY_SELL_FLAG`, `UL_STOCKS_COMPNAME_TYPE`, `UL_STOCKS_Qtr_Data_Publish`) VALUES
(100114, 'Cheelizza Pizza India Limited', 'cheelizza-pizza-india-limited', 'images/company-logo/cheelizza-pizza-india-limited.png', 142, 'Other', 'INE0MSX01027', 'Cheelizza Pizza India', NULL, NULL, 'pre_ipo', NULL, '2021', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Cheelizza Pizza India Private Limited, incorporated on 12 February 2021 and registered in Mumbai, runs a home-grown vegetarian pizza brand within India\'s QSR space, blending local taste with a modern quick-service format. The company started with modest authorised capital (₹0.16 million) and paid-up capital (₹0.13 million), and by early 2024 had grown to around 160 employees, with revenue growth exceeding 300% year-on-year — though profit margins came under pressure given the investment going into expansion.\n\nBy mid-2025, Cheelizza had grown to around four outlets in Mumbai, with new stores planned in other cities including Rajkot, Gujarat. The brand has stayed away from aggressive franchising so far, preferring to retain ownership and control of its outlets to keep operations and service quality consistent as it grows.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100115, 'Fusion Techstack Limited', 'fusion-techstack-limited', 'images/company-logo/fusion-techstack-limited.png', 51, 'Finance - Stock Broking', 'INE678L01012', 'Fusion Techstack', NULL, NULL, 'pre_ipo', NULL, '2008', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.icexindia.com/', NULL, 'Fusion Techstack Limited, incorporated on 18 August 2008, operated for most of its history as Indian Commodity Exchange Limited (ICEX), a SEBI-regulated national commodity derivatives exchange headquartered in Navi Mumbai. ICEX ran a demutualised, fully electronic trading platform and built a name for itself as the first exchange in the world to launch a diamond derivatives contract, in 2017, later adding contracts such as Steel Long and absorbing the National Multi-Commodity Exchange (NMCE) in FY19 following NCLT approval.\r\n\r\nIn late 2024, SEBI approved ICEX\'s exit from the commodity exchange business, and its exchange recognition was formally withdrawn in January 2025. Shareholders subsequently approved changing the company\'s name from Indian Commodity Exchange Limited to Fusion Techstack Limited, along with a revision of its core objects, to pursue new business activities in technology and data services — a change the Ministry of Corporate Affairs approved in September 2025. For FY25, the company reported revenue of around ₹6 crore with a small in-house team. Its board is now led by CEO Tridibnath Swain, alongside directors including Suresh Babu Konakanchi and Gopala Ramaratnam. The company\'s post-pivot business in technology and data services is still taking shape and has not yet been fully disclosed publicly.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '3', '2500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100116, 'Assam Carbon Products Limited', 'assam-carbon-products-limited', 'images/company-logo/assam-carbon-products-limited.png', NULL, 'Mining & Minerals', 'INE496C01018', 'Assam Carbon Products', NULL, NULL, 'pre_ipo', NULL, '1951', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Assam Carbon Products Limited (ACPL), established in 1951, manufactures carbon and graphite products for industries including steel, aluminium and electrical, and has built a long-standing reputation as a trusted supplier to well-known companies in India and abroad.\n\nQuality has been a consistent differentiator for the company, alongside a focus on sustainability — including the use of environmentally friendly materials, energy-efficient manufacturing and investment in renewable energy for its facilities. That combination of quality, sustainability and customer service has helped ACPL build a loyal customer base and a reputation as a reliable carbon-and-graphite-products supplier.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '5', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100117, 'Downtown Hospital Ltd', 'downtown-hospital-ltd', 'images/company-logo/downtown-hospital-ltd.png', NULL, 'Hospital & Healthcare Services', 'INE06NN01012', 'Downtown Hospital', NULL, NULL, 'pre_ipo', NULL, '1986', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://downtownhospitals.in/', NULL, 'Downtown Hospital, commissioned on 15 February 1989, was the first multi-speciality corporate hospital in Northeast India and has completed more than 30 years of service. It provides medical care not just to people across the Northeast but also to patients from neighbouring countries including Bhutan, Nepal, Bangladesh, Myanmar, Cambodia, Laos and Vietnam.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100118, 'RRP S4E Innovation Private Limited', 'rrp-s4e-innovation-private-limited', 'images/company-logo/rrp-s4e-innovation-private-limited.png', 156, 'Defence / Aerospace', 'INE09FT01019', 'RRP S4E Innovation', NULL, NULL, 'pre_ipo', NULL, '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.rrps4e.in/', NULL, 'RRP S4E Innovation, headquartered in Navi Mumbai with manufacturing at Mahape\'s TTC Industrial Area, develops advanced electro-optic systems for defence and tactical applications, positioning itself around what it calls \"battlefield superiority.\" The company\'s product range spans reflex sights, telescopic sights, night vision devices, thermal and hybrid imaging systems, helmet-mounted night vision, and surveillance equipment, alongside border-security systems covering both land and aerial (drone-in-a-box) platforms.\n\nBeyond manufacturing, RRP S4E also runs an Electro-Optic Repair and Restoration (EORC) division, offering component-level repairs, fault diagnosis, sensor diagnostics, full system overhauls and precision testing for thermal imagers, surveillance payloads, stabilised systems and other mission-critical optical equipment — aimed at extending the operational life of fielded systems rather than requiring full replacement.\n\nThe company draws on more than three decades of engineering experience in precision manufacturing and nano-machining, and works with partners including Israel\'s Meprolight, state-owned defence major Bharat Electronics Limited (BEL), Microavia and Optix. It positions its manufacturing and engineering base in India as a \"Make in India\" play, aimed at giving it faster response times and greater control over its supply chain. RRP S4E also sits within a broader RRP Group structure that includes RRP Defense, RRP Electronics and RRP Drones as related group entities, reflecting a wider footprint across India\'s defence-technology ecosystem.', '6', '2026-08-24 16:10:51', '2026-08-25 07:39:41', '4', '4', '100', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100119, 'Machint Solutions Limited', 'machint-solutions-limited', 'images/company-logo/machint-solutions-limited.png', NULL, 'IT - Networking', 'INE0ZD001015', 'Machint Solutions', NULL, NULL, 'pre_ipo', 'September', '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.machint.com/', NULL, 'Machint Solutions Limited, incorporated on 26 September 2018 and headquartered in Hyderabad, is an IT services and consulting company working on hyper-automation and intelligent automation aimed at helping organisations run more efficiently. Its offerings span Business Process Management, Robotic Process Automation, Generative AI, AI/ML, data science, digital engineering and business consulting.\n\nClients span banking, financial services, healthcare, automotive and the public sector, with the company positioning its blend of technology and global delivery capability as a way to help organisations move faster on digital transformation while creating measurable business value.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100120, 'Ecosure Pulpmolding Technologies Limited', 'ecosure-pulpmolding-technologies-limited', 'images/company-logo/ecosure-pulpmolding-technologies-limited.png', 142, 'Other', 'INE0K3N01021', 'Ecosure Pulpmolding', NULL, NULL, 'pre_ipo', NULL, '2019', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Ecosure Pulpmolding Technologies Limited focuses on eco-friendly packaging built around pulp-moulding technology, offering sustainable, biodegradable and compostable alternatives to plastic and other less environmentally friendly materials. Its product range includes moulded pulp trays, containers and packaging for industries such as food and beverage, electronics and consumer goods.\n\nThe company works to keep its manufacturing aligned with international sustainability standards, aiming for products that are both functional and environmentally conscious. Serving domestic and international markets, Ecosure positions itself as part of the broader shift toward greener packaging driven by tightening environmental regulation and shifting consumer preference.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '15000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100121, 'Amol Minechem Limited', 'amol-minechem-limited', 'images/company-logo/amol-minechem-limited.png', NULL, 'Chemicals', 'INE404C01012', 'Amol Minechem', NULL, NULL, 'pre_ipo', NULL, '1979', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.amolminechem.com/', NULL, 'Amol Minechem Limited, formerly Amol Dicalite Limited and established in 1979, was the first company in India to produce Perlite Filteraid and other Perlite-based products, achieved through a collaboration with Grefco, Inc. of the USA, a pioneer in global Perlite technology. Manufacturing began in 1982, with the corporate office in Ahmedabad and the production plant in Kadi, Mehsana district, about 50 km north of the city.\n\nThe company played an early role in import substitution by bringing Perlite Filteraid to Indian markets, starting from a modest 600 MT annual capacity and growing into the industry\'s market leader. Over the years it has built out customised solutions, value-added products and turnkey services for clients globally, and has also carved out a strong position in Cryogenic Perlite Insulation, now ranked among the top three players worldwide in that specialised segment. A focus on reliability, efficiency and cost-effective solutions has helped Amol Minechem build lasting customer relationships.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '5', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100122, 'Zak Venture Ltd', 'zak-venture-ltd', 'images/company-logo/zak-venture-ltd.png', 142, 'Other', 'INE15YC01013', 'Zak Venture', NULL, NULL, 'pre_ipo', 'March', '2016', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://zakventure.com/', NULL, 'Zak Venture Ltd, incorporated on 14 March 2016 and headquartered in Noida, Uttar Pradesh, works across infrastructure and energy solutions, primarily in oil & gas and clean energy. Its offerings span natural gas pipeline infrastructure, compressed biogas (CBG)/bio-CNG projects, and Auto LPG dispensing stations.\n\nWith more than eight years of experience, Zak Venture has positioned itself as a partner to City Gas Distribution companies and other players across the energy value chain, providing execution, development and operations support for gas infrastructure and sustainable fuel projects aimed at improving energy reliability and supporting environmental goals in India.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100123, 'Silverline Technologies Limited', 'silverline-technologies-limited', 'images/company-logo/silverline-technologies-limited.png', NULL, 'IT - Hardware', 'INE368A01021', 'Silverline Technologies', NULL, NULL, 'pre_ipo', NULL, '1992', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Silverline Technologies Ltd., formerly known as Silverline Industries Ltd., is a global provider of software, business solutions and technology consulting, built around helping businesses navigate digital disruption and cultural change. The company works across IT services, consulting and business solutions, and was ranked India\'s seventh-largest software company by NASSCOM in 2002.\n\nSilverline was the first Indian company to open a development centre in the United States, back in 1994. It now serves clients across sectors such as retail, consumer goods, building materials, banking, insurance, high-tech, engineering, manufacturing, automotive and hospitality, with operations spanning the US, India, Canada, the UK, Germany, Hong Kong, Japan and Egypt.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '10000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100124, 'Mayasheel Retail India Limited - Bazar India', 'mayasheel-retail-india-limited-bazar-india', 'images/company-logo/mayasheel-retail-india-limited-bazar-india.png', NULL, 'Retailing', 'INE03NO01017', 'Bazar India', NULL, NULL, 'pre_ipo', NULL, '2006', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'http://www.bazarindia.co/', NULL, 'Bazar India, operating as Mayasheel Retail India Limited, was established in 2006 and is headquartered in Delhi. The company runs a chain of retail stores offering clothing, footwear, home furnishings and personal-care products, with an emphasis on keeping quality products affordable.\n\nPartnerships with established manufacturers and suppliers help ensure a broad product range for customers, and the stores are designed around a convenient, welcoming shopping experience. Bazar India also engages in corporate social responsibility, supporting education, healthcare and environmental initiatives.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '3', '3', '500', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100125, 'NCL Holdings', 'ncl-holdings', 'images/company-logo/ncl-holdings.png', 142, 'Other', 'INE06DT01010', 'NCL Holdings', NULL, NULL, 'pre_ipo', 'January', '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://nclholdings.in/', NULL, 'NCL Holdings (A&S) Limited, incorporated on 5 January 2018 (CIN: U68100TG2018PLC121664) and headquartered in Hyderabad, was originally set up as a holding company to acquire the non-building-materials business of NCL Buildtek Ltd, through a scheme of arrangement sanctioned by the National Company Law Tribunal on 24 January 2019. Its core purpose is holding and managing investments in corporate and non-corporate entities involved in manufacturing, trading and services.\n\nGroup companies under NCL Holdings include NCL Green Habitats Pvt Ltd (real estate and land/farm purchase and development), Eastern Ghat Renewable Energy Company (hydropower generation), Sun Crop Sciences Pvt Ltd (agro-seeds, R&D and distribution), and Kakatiya Industries Pvt Ltd (chemicals and a hydropower division).', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '250', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100126, 'Market Simplified India Ltd', 'market-simplified-india-ltd', 'images/company-logo/market-simplified-india-ltd.png', 65, 'IT - Software', 'INE931L01015', 'Market Simplified', NULL, NULL, 'pre_ipo', NULL, '2000', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.marketsimplified.com/', NULL, 'Market Simplified India Limited, with more than 15 years in the industry, has built a digital-acceleration offering powered by what it calls experience engineering — combining market expertise, technology and adaptability to client needs. Its team of consultants and developers provides end-to-end services covering software design, business analysis backed by prototyping and data visualisation, QA and testing, development, hosting, support and maintenance.\n\nWorking with banks, brokerages, fintechs and organisations more broadly, the company has positioned itself around helping clients rethink the role of finance in their growth and transformation initiatives, a brand identity it has continued to build on.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100127, 'Madbow Ventures Limited', 'madbow-ventures-limited', 'images/company-logo/madbow-ventures-limited.png', 155, 'e-Commerce', 'INE0JKD01022', 'Madbow', NULL, NULL, 'pre_ipo', NULL, '2016', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.madbow.com/', NULL, 'MADBOW, founded in 2016, is a lifestyle fashion brand built around creative, distinctive clothing for trendy, contemporary women, and ranks among the leading suppliers of ready-to-wear garments, footwear and lingerie in its segment. The brand was built on ideas of impact through fashion, honesty and thoughtfulness, and now runs with a team of more than 100 people, having sold around 1 million products to date.\n\nThe company leans into experimentation to balance creativity with relatability in its designs, keeping its range fresh and current. Its approach centres on the idea that customer loyalty — not brand alone — drives a business, which shapes its focus on offering well-fitted, functional, fashion-forward garments at accessible prices.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '3', '1000', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100128, 'Shivchem Agro Limited', 'shivchem-agro-limited', 'images/company-logo/shivchem-agro-limited.png', NULL, 'Agriculture', 'INE18CU01023', 'Shivchem Agro', NULL, NULL, 'pre_ipo', 'September', '2021', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://shivchemagro.com/', NULL, 'Shivchem Agro Limited, incorporated on 12 September 2021 and headquartered in Delhi, is an agrochemical manufacturer and crop-protection solutions provider. The company develops, manufactures, stocks and distributes agricultural inputs including insecticides, fungicides, herbicides, plant-growth regulators, rodenticides and fertilisers, aimed at helping farmers protect crops and improve yields.\n\nWith a growing distribution network across multiple states and a modern manufacturing facility, Shivchem Agro emphasises product quality, innovation and farmer support through technical guidance, and has grown from a private entity into a public limited company as it works to strengthen its position in Indian agriculture.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '4', '4', '1600', 'No', 'Both', 'Yes', 'unlisted', 'No'),
(100129, 'Matrix Gas and Renewables Limited', 'matrix-gas-and-renewables-limited', 'images/company-logo/matrix-gas-and-renewables-limited.png', NULL, 'Gas Transmission/Marketing', 'INE0PO201010', 'Matrix Gas and Renewables', NULL, NULL, 'pre_ipo', NULL, '2018', '1', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.matrixgas.in/', NULL, 'Matrix Gas and Renewables Limited works across natural gas and renewable energy, positioning itself around providing cleaner alternatives to traditional fossil fuels. Its portfolio spans the production and distribution of natural gas alongside investments in renewable sources such as wind, solar and bioenergy.\n\nThe company also offers consultancy services to businesses moving toward greener energy, framing its broader goal around reducing carbon emissions and promoting energy efficiency as part of a more sustainable, resilient energy landscape.', '6', '2026-08-24 16:10:51', '2026-08-24 16:10:51', '5', '3', '2000', 'No', 'Both', 'Yes', 'unlisted', 'No');
